    NARROW_PASSAGE = "narrow_passage"  # Requires AGILITY
    COMPLEX_MECHANISM = "complex_mechanism"  # Requires INTELLIGENCE
    TRAP_DISARM = "trap_disarm"  # Requires STEALTH

class GameState(Enum):
    """Current state of the game."""
    WAITING = "waiting"        # Waiting for players to join
    IN_PROGRESS = "in_progress"  # Game is active
    FINISHED = "finished"      # Game has ended

