    treasures_collected: int = 0
    is_online: bool = True
    position: Tuple[int, int] = (0, 0)  # (x, y) coordinates

    def collect_treasure(self) -> None:
        """Player collects a treasure."""
        self.treasures_collected += 1

    def move(self, new_position: Tuple[int, int]) -> None:
        """Move player to new position."""
        self.position = new_position

    def disconnect(self) -> None:
        """Mark player as disconnected."""
        self.is_online = False

    def reconnect(self) -> None:
        """Mark player as reconnected."""
        self.is_online = True

    def __str__(self) -> str:
        return f"{self.name} ({self.ability.value})"

@dataclass
class Team:
    """Represents a team of players."""
    team_id: str
    name: str
    players: List[Player] = field(default_factory=list)
    treasures_collected: int = 0
    current_environment: EnvironmentType = EnvironmentType.FOREST
    position_in_environment: int = 0  # Progress within current environment
    start_time: Optional[float] = None
    finish_time: Optional[float] = None

    def add_player(self, player: Player) -> bool:
        """Add a player to the team if there's space."""
        if len(self.players) >= 4:
            return False
        self.players.append(player)
        return True

    def remove_player(self, player_id: str) -> Optional[Player]:
        """Remove a player from the team."""
        for i, player in enumerate(self.players):
            if player.player_id == player_id:
                return self.players.pop(i)
        return None

    def collect_team_treasure(self) -> None:
        """Team collects a treasure."""
        self.treasures_collected += 1

    def get_online_players(self) -> List[Player]:
        """Get list of online players."""
        return [p for p in self.players if p.is_online]

    def has_ability(self, ability: Ability) -> bool:
        """Check if team has a player with specific ability."""
        return any(player.ability == ability for player in self.get_online_players())

    def calculate_score(self) -> float:
        """Calculate team score based on treasures and time."""
        if self.finish_time is None or self.start_time is None:
            return self.treasures_collected * 100

        time_taken = self.finish_time - self.start_time
        time_bonus = max(0, 1000 - time_taken)  # Bonus for finishing quickly
        treasure_score = self.treasures_collected * 100

        return treasure_score + time_bonus

    def __str__(self) -> str:
        return f"{self.name} ({len(self.players)} players, {self.treasures_collected} treasures)"

@dataclass
class Puzzle:
