# solution.py

import random
from enum import Enum
from typing import List, Dict, Tuple, Optional, Set
from dataclasses import dataclass, field
import heapq

# ==================== ENUMS AND DATA CLASSES ====================

class AgentRole(Enum):
    """Defines possible roles for AI agents."""
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"
    SUPPORT = "support"

class Ability(Enum):
    """Defines special abilities agents can have."""
    INCREASED_SPEED = "increased_speed"
    HEALING = "healing"
    SHIELDING = "shielding"
    STEALTH = "stealth"
    DOUBLE_DAMAGE = "double_damage"

class ObjectiveType(Enum):
    """Types of objectives in levels."""
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"

class MessageType(Enum):
    """Types of messages agents can send."""
    ENEMY_LOCATION = "enemy_location"
    OBJECTIVE_STATUS = "objective_status"
    STRATEGIC_PLAN = "strategic_plan"
    REQUEST_HELP = "request_help"
    AGENT_STATUS = "agent_status"

@dataclass
class Position:
    """Represents a 2D position in the game grid."""
    x: int
    y: int

    def distance(self, other: 'Position') -> float:
        """Calculate Euclidean distance to another position."""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __hash__(self):
        return hash((self.x, self.y))

@dataclass
class Message:
    """Represents a communication message between agents."""
    sender_id: int
    message_type: MessageType
    content: Dict
    timestamp: int  # game turn when sent

@dataclass
class Agent:
    """Represents an AI agent in the game."""
    agent_id: int
    role: AgentRole
    position: Position
    health: int = 100
    max_health: int = 100
    abilities: List[Ability] = field(default_factory=list)
    speed: int = 1  # cells per turn
    attack_power: int = 10
    defense: int = 5
    inventory: List[str] = field(default_factory=list)  # e.g., ["flag"]
    is_alive: bool = True
    communication_range: int = 10  # distance within which messages can be sent/received
    last_action: str = ""

    def move(self, new_position: Position, environment: 'GameEnvironment') -> bool:
        """Attempt to move to a new position."""
        if not environment.is_valid_position(new_position):
            self.last_action = f"Failed to move to {new_position}"
            return False

        if Ability.INCREASED_SPEED in self.abilities:
            # Can move 2 cells with increased speed
            if self.position.distance(new_position) <= 2:
                self.position = new_position
                self.last_action = f"Moved to {new_position}"
                return True
        else:
            if self.position.distance(new_position) <= 1:
                self.position = new_position
                self.last_action = f"Moved to {new_position}"
                return True
        self.last_action = f"Failed to move to {new_position} (too far)"
        return False

    def attack(self, target: 'Agent') -> int:
        """Attack another agent."""
        if not target.is_alive:
            self.last_action = f"Tried to attack dead agent {target.agent_id}"
            return 0

        damage = self.attack_power
        if Ability.DOUBLE_DAMAGE in self.abilities:
            damage *= 2

        actual_damage = max(1, damage - target.defense)
        target.health -= actual_damage

        if target.health <= 0:
            target.is_alive = False
            target.health = 0
            self.last_action = f"Eliminated agent {target.agent_id}"
        else:
            self.last_action = f"Attacked agent {target.agent_id} for {actual_damage} damage"

        return actual_damage

    def heal(self, target: 'Agent') -> bool:
        """Heal another agent (requires healing ability)."""
        if Ability.HEALING not in self.abilities:
            self.last_action = "No healing ability"
            return False

        if not target.is_alive:
            self.last_action = f"Cannot heal dead agent {target.agent_id}"
            return False

        heal_amount = 20
        target.health = min(target.max_health, target.health + heal_amount)
        self.last_action = f"Healed agent {target.agent_id} for {heal_amount} health"
        return True

    def use_shield(self) -> None:
        """Activate shielding ability."""
        if Ability.SHIELDING in self.abilities:
            self.defense += 10
            self.last_action = "Shield activated"

    def can_communicate(self, other_position: Position) -> bool:
        """Check if communication is possible with agent at given position."""
        return self.position.distance(other_position) <= self.communication_range

@dataclass
class Objective:
    """Represents a game objective."""
    objective_type: ObjectiveType
    position: Position
    is_completed: bool = False
    progress: float = 0.0  # 0.0 to 1.0
    required_agents: int = 1  # number of agents needed to complete
    agents_on_objective: Set[int] = field(default_factory=set)  # agent IDs

@dataclass
class Level:
    """Represents a game level with objectives and layout."""
    level_id: int
    name: str
    objectives: List[Objective]
    grid_size: Tuple[int, int]  # (width, height)
    obstacles: Set[Position] = field(default_factory=set)  # impassable cells
    enemy_spawn_points: List[Position] = field(default_factory=list)

# ==================== GAME ENVIRONMENT ====================

class GameEnvironment:
    """Main game environment managing agents, levels, and game state."""

    def __init__(self):
        self.agents: Dict[int, Agent] = {}
        self.enemy_agents: Dict[int, Agent] = {}
        self.current_level: Optional[Level] = None
        self.messages: List[Message] = []
        self.turn_count: int = 0
        self.score: int = 0
        self.agent_counter: int = 0
        self.enemy_counter: int = 0

    def create_agent(self, role: AgentRole, position: Position, abilities: List[Ability] = None) -> int:
        """Create a new agent and return its ID."""
        if abilities is None:
            abilities = []

        # Set role-specific attributes
        attack_power = 10
        defense = 5
        speed = 1

        if role == AgentRole.ATTACKER:
            attack_power = 20
            abilities.append(Ability.DOUBLE_DAMAGE)
        elif role == AgentRole.DEFENDER:
            defense = 15
            abilities.append(Ability.SHIELDING)
        elif role == AgentRole.SCOUT:
            speed = 2
            abilities.append(Ability.INCREASED_SPEED)
            abilities.append(Ability.STEALTH)
        elif role == AgentRole.SUPPORT:
            abilities.append(Ability.HEALING)

        agent_id = self.agent_counter
        self.agents[agent_id] = Agent(
            agent_id=agent_id,
            role=role,
            position=position,
            abilities=abilities,
            attack_power=attack_power,
            defense=defense,
            speed=speed
        )
        self.agent_counter += 1
        return agent_id

    def create_enemy_agent(self, position: Position) -> int:
        """Create an enemy agent."""
        enemy_id = self.enemy_counter
        self.enemy_agents[enemy_id] = Agent(
            agent_id=enemy_id,
            role=AgentRole.ATTACKER,  # Enemies are always attackers
            position=position,
            health=50,
            max_health=50,
            attack_power=15,
            defense=3
        )
        self.enemy_counter += 1
        return enemy_id

    def load_level(self, level: Level) -> None:
        """Load a level into the environment."""
        self.current_level = level
        self.turn_count = 0
        self.messages.clear()

        # Spawn enemies at spawn points
        for spawn_point in level.enemy_spawn_points:
            self.create_enemy_agent(spawn_point)

    def is_valid_position(self, position: Position) -> bool:
        """Check if a position is within bounds and not an obstacle."""
        if not self.current_level:
            return False

        width, height = self.current_level.grid_size
        if not (0 <= position.x < width and 0 <= position.y < height):
            return False

        if position in self.current_level.obstacles:
            return False

        return True

    def send_message(self, sender_id: int, message_type: MessageType, content: Dict) -> None:
        """Send a message from an agent."""
        if sender_id not in self.agents:
            return

        message = Message(
            sender_id=sender_id,
            message_type=message_type,
            content=content,
            timestamp=self.turn_count
        )
        self.messages.append(message)

    def get_messages_for_agent(self, agent_id: int) -> List[Message]:
        """Get all messages that an agent can receive (within communication range)."""
        if agent_id not in self.agents:
            return []

        agent = self.agents[agent_id]
        recent_messages = []

        for message in self.messages[-100:]:  # Last 100 messages
            # Check if sender is within range
            sender = self.agents.get(message.sender_id)
            if sender and agent.can_communicate(sender.position):
                recent_messages.append(message)

        return recent_messages

    def update_objectives(self) -> None:
        """Update completion status of all objectives."""
        if not self.current_level:
            return

        for objective in self.current_level.objectives:
            if objective.is_completed:
                continue

            if objective.objective_type == ObjectiveType.CAPTURE_FLAG:
                # Check if any agent has the flag in inventory
                for agent in self.agents.values():
                    if "flag" in agent.inventory and agent.is_alive:
                        objective.is_completed = True
                        objective.progress = 1.0
                        self.score += 100
                        break

            elif objective.objective_type == ObjectiveType.DEFEND_BASE:
                # Base is defended if no enemies are near it
                enemies_near_base = 0
                for enemy in self.enemy_agents.values():
                    if enemy.is_alive and enemy.position.distance(objective.position) <= 3:
                        enemies_near_base += 1

                if enemies_near_base == 0:
                    objective.progress = min(1.0, objective.progress + 0.1)
                    if objective.progress >= 1.0:
                        objective.is_completed = True
                        self.score += 150

            elif objective.objective_type == ObjectiveType.ELIMINATE_ENEMIES:
                # Check if all enemies are eliminated
                alive_enemies = sum(1 for e in self.enemy_agents.values() if e.is_alive)
