# solution.py
"""
Board_Game_Team_Challenge - A multi-agent system for collaborative board gameplay
Main application file containing all components in a single file
"""

import asyncio
import json
import uuid
from datetime import datetime
from typing import Dict, List, Optional, Any, Set
from enum import Enum
from dataclasses import dataclass, field, asdict
import random
from collections import defaultdict

# ==================== DATABASE MODELS ====================

@dataclass
class PlayerProfile:
    """Player profile data model"""
    player_id: str
    username: str
    email: str
    created_at: datetime
    total_games: int = 0
    wins: int = 0
    losses: int = 0
    average_score: float = 0.0
    preferred_strategies: List[str] = field(default_factory=list)
    team_history: List[str] = field(default_factory=list)

@dataclass
class Team:
    """Team data model"""
    team_id: str
    name: str
    created_at: datetime
    members: List[str] = field(default_factory=list)  # player_ids
    current_game: Optional[str] = None
    game_history: List[Dict[str, Any]] = field(default_factory=list)
    win_rate: float = 0.0

@dataclass
class GameBoard:
    """Game board representation"""
    board_id: str
    game_type: str
    dimensions: tuple  # (width, height)
    cells: Dict[tuple, Any] = field(default_factory=dict)  # (x, y): cell_data
    pieces: Dict[str, Dict] = field(default_factory=dict)  # piece_id: {position, type, owner}
    state: Dict[str, Any] = field(default_factory=dict)

@dataclass
class GameSession:
    """Active game session"""
    session_id: str
    game_type: str
    created_at: datetime
    team_id: str
    board_id: str
    players: List[str]
    current_turn: str
    turn_order: List[str]
    status: str  # "waiting", "active", "completed", "paused"
    move_history: List[Dict] = field(default_factory=list)
    objectives: List[Dict] = field(default_factory=list)
    difficulty: str = "medium"
    chat_messages: List[Dict] = field(default_factory=list)

# ==================== DATABASE SIMULATION ====================

class Database:
    """Simulated database for storing game data"""

    def __init__(self):
        self.players: Dict[str, PlayerProfile] = {}
        self.teams: Dict[str, Team] = {}
        self.boards: Dict[str, GameBoard] = {}
        self.sessions: Dict[str, GameSession] = {}
        self.game_history: List[Dict] = []

    def save_player(self, player: PlayerProfile) -> None:
        """Save player profile to database"""
        self.players[player.player_id] = player

    def get_player(self, player_id: str) -> Optional[PlayerProfile]:
        """Retrieve player profile"""
        return self.players.get(player_id)

    def save_team(self, team: Team) -> None:
        """Save team to database"""
        self.teams[team.team_id] = team

    def get_team(self, team_id: str) -> Optional[Team]:
        """Retrieve team"""
        return self.teams.get(team_id)

    def save_board(self, board: GameBoard) -> None:
        """Save game board"""
        self.boards[board.board_id] = board

    def get_board(self, board_id: str) -> Optional[GameBoard]:
        """Retrieve game board"""
        return self.boards.get(board_id)

    def save_session(self, session: GameSession) -> None:
        """Save game session"""
        self.sessions[session.session_id] = session

    def get_session(self, session_id: str) -> Optional[GameSession]:
        """Retrieve game session"""
        return self.sessions.get(session_id)

    def record_game_history(self, game_data: Dict) -> None:
        """Record completed game for analytics"""
        self.game_history.append(game_data)

    def get_player_stats(self, player_id: str) -> Dict[str, Any]:
        """Get player statistics"""
        player = self.get_player(player_id)
        if not player:
            return {}

        return {
            "player_id": player.player_id,
            "username": player.username,
            "total_games": player.total_games,
            "wins": player.wins,
            "losses": player.losses,
            "win_rate": player.wins / player.total_games if player.total_games > 0 else 0,
            "average_score": player.average_score,
            "preferred_strategies": player.preferred_strategies
        }

    def get_team_stats(self, team_id: str) -> Dict[str, Any]:
        """Get team statistics"""
        team = self.get_team(team_id)
        if not team:
            return {}

        return {
            "team_id": team.team_id,
            "name": team.name,
            "member_count": len(team.members),
            "current_game": team.current_game,
            "games_played": len(team.game_history),
            "win_rate": team.win_rate,
            "recent_games": team.game_history[-5:] if team.game_history else []
        }

# ==================== GAME ENGINE ====================

class GameEngine:
    """Core game logic and rule enforcement"""

    def __init__(self, db: Database):
