class ConnectionManager:
    """Manage WebSocket connections for real-time communication"""

    def __init__(self):
        self.active_connections: Dict[str, Any] = {}
        self.room_connections: Dict[str, Set[str]] = defaultdict(set)

    async def connect(self, websocket: Any, client_id: str, session_id: str):
        """Handle new WebSocket connection"""
        self.active_connections[client_id] = websocket
        self.room_connections[session_id].add(client_id)

    async def disconnect(self, client_id: str, session_id: str):
        """Handle WebSocket disconnection"""
        self.active_connections.pop(client_id, None)
        self.room_connections[session_id].discard(client_id)

    async def broadcast_to_room(self, session_id: str, message: Dict):
        """Send message to all connections in a room"""
        if session_id in self.room_connections:
            for client_id in self.room_connections[session_id]:
                if client_id in self.active_connections:
                    try:
                        await self.active_connections[client_id].send_json(message)
                    except Exception as e:
                        print(f"Error sending to {client_id}: {e}")

    async def send_personal_message(self, client_id: str, message: Dict):
        """Send message to specific client"""
        if client_id in self.active_connections:
            try:
                await self.active_connections[client_id].send_json(message)
            except Exception as e:
                print(f"Error sending to {client_id}: {e}")

