class GameEngine:
    """Core game logic and rule enforcement"""

    def __init__(self, db: Database):
        self.db = db
        self.valid_moves_cache: Dict[str, Set] = {}

    def validate_move(self, session_id: str, player_id: str, move: Dict) -> bool:
        """Validate if a move is legal according to game rules"""
        session = self.db.get_session(session_id)
        if not session:
            return False

        # Check if it's player's turn
        if session.current_turn != player_id:
            return False

        # Basic move validation (can be extended for specific game types)
        required_fields = {"action", "data", "timestamp"}
        if not all(field in move for field in required_fields):
            return False

        # Game-specific validation would go here
        return True

    def apply_move(self, session_id: str, move: Dict) -> Dict[str, Any]:
        """Apply a validated move to the game state"""
        session = self.db.get_session(session_id)
        if not session:
            return {"success": False, "error": "Session not found"}

        # Add move to history
        session.move_history.append(move)

        # Update game state based on move
        board = self.db.get_board(session.board_id)
        if not board:
            return {"success": False, "error": "Board not found"}

        # Process different action types
        action = move["data"].get("action_type")

        if action == "move_piece":
            piece_id = move["data"]["piece_id"]
            new_pos = tuple(move["data"]["position"])

            # Update piece position
            if piece_id in board.pieces:
                board.pieces[piece_id]["position"] = new_pos

        elif action == "place_piece":
            piece_id = f"piece_{len(board.pieces) + 1}"
            board.pieces[piece_id] = {
                "position": tuple(move["data"]["position"]),
                "type": move["data"]["piece_type"],
                "owner": move["player_id"]
            }

        # Update turn order
        current_idx = session.turn_order.index(session.current_turn)
        next_idx = (current_idx + 1) % len(session.turn_order)
        session.current_turn = session.turn_order[next_idx]

        # Check win conditions
        winner = self.check_win_condition(session_id)
        if winner:
            session.status = "completed"
            self.end_game(session_id, winner)

        # Save updates
        self.db.save_board(board)
        self.db.save_session(session)

        return {"success": True, "next_turn": session.current_turn}

    def check_win_condition(self, session_id: str) -> Optional[str]:
        """Check if any player/team has won"""
        session = self.db.get_session(session_id)
        board = self.db.get_board(session.board_id)

        # Simple win condition for demonstration
        # In a real game, this would be much more complex
        objectives_completed = 0
        for objective in session.objectives:
            if objective.get("completed", False):
                objectives_completed += 1

        if objectives_completed >= len(session.objectives):
            return session.team_id  # Team wins

        return None

    def end_game(self, session_id: str, winner: str) -> None:
        """Handle game completion"""
        session = self.db.get_session(session_id)

        # Update player stats
        for player_id in session.players:
            player = self.db.get_player(player_id)
            if player:
                player.total_games += 1
                if player_id in winner:  # Simplified winner check
                    player.wins += 1
                else:
                    player.losses += 1
                self.db.save_player(player)

        # Update team stats
        team = self.db.get_team(session.team_id)
        if team:
            team.game_history.append({
                "session_id": session_id,
                "completed_at": datetime.now(),
                "winner": winner,
                "duration": (datetime.now() - session.created_at).total_seconds()
            })

            # Calculate win rate
            wins = sum(1 for game in team.game_history if game.get("winner") == team.team_id)
            team.win_rate = wins / len(team.game_history) if team.game_history else 0
            team.current_game = None
            self.db.save_team(team)

        # Record game history for analytics
        game_data = {
            "session_id": session_id,
            "game_type": session.game_type,
            "team_id": session.team_id,
            "players": session.players,
            "winner": winner,
            "moves_count": len(session.move_history),
            "duration": (datetime.now() - session.created_at).total_seconds(),
            "completed_at": datetime.now(),
            "difficulty": session.difficulty
        }
        self.db.record_game_history(game_data)

