        """Add an expense for this user."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive")

        # Create expense
        expense = Expense(
            id=str(uuid.uuid4()),
            user_id=self.id,
            amount=amount,
            category=category,
            description=description
        )

        # Update budget category
        if category not in self.budget_categories:
            self.budget_categories[category] = BudgetCategory(category=category, limit=0)

        self.budget_categories[category].add_expense(amount)
        self.expenses.append(expense)
        return expense

    def set_budget_limit(self, category: ExpenseCategory, limit: float) -> None:
        """Set budget limit for a specific category."""
        if limit < 0:
            raise ValueError("Budget limit cannot be negative")

        if category not in self.budget_categories:
            self.budget_categories[category] = BudgetCategory(category=category, limit=limit)
        else:
            self.budget_categories[category].adjust_limit(limit)

    def get_total_spent(self) -> float:
