"""
MultiAgentBudgetOptimizer: A collaborative budget management system for multiple users.
This application allows users to manage shared budgets, track expenses, and optimize spending.
"""

from typing import Dict, List, Optional, Tuple, Set
from dataclasses import dataclass, field
from enum import Enum
import json
from datetime import datetime
from abc import ABC, abstractmethod
import uuid


class ExpenseCategory(Enum):
    """Enumeration of supported expense categories."""
    GROCERIES = "Groceries"
    ENTERTAINMENT = "Entertainment"
    UTILITIES = "Utilities"
    TRANSPORTATION = "Transportation"
    DINING = "Dining"
    SHOPPING = "Shopping"
    OTHER = "Other"


@dataclass
class Expense:
    """Data class representing a single expense entry."""
    id: str
    user_id: str
    amount: float
    category: ExpenseCategory
    description: str
    date: str = field(default_factory=lambda: datetime.now().strftime("%Y-%m-%d"))

    def to_dict(self) -> Dict:
        """Convert expense to dictionary for serialization."""
        return {
            "id": self.id,
            "user_id": self.user_id,
            "amount": self.amount,
            "category": self.category.value,
            "description": self.description,
            "date": self.date
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Expense':
        """Create expense from dictionary."""
        return cls(
            id=data["id"],
            user_id=data["user_id"],
            amount=data["amount"],
            category=ExpenseCategory(data["category"]),
            description=data["description"],
            date=data["date"]
        )


@dataclass
class BudgetCategory:
    """Data class representing budget allocation for a specific category."""
    category: ExpenseCategory
    limit: float
    spent: float = 0.0

    @property
    def remaining(self) -> float:
        """Calculate remaining budget for this category."""
        return max(0, self.limit - self.spent)

    @property
    def utilization_percentage(self) -> float:
        """Calculate budget utilization percentage."""
        return (self.spent / self.limit * 100) if self.limit > 0 else 0

    def add_expense(self, amount: float) -> None:
        """Add expense to this category."""
        if amount < 0:
            raise ValueError("Expense amount cannot be negative")
        self.spent += amount

    def adjust_limit(self, new_limit: float) -> None:
        """Adjust the budget limit for this category."""
        if new_limit < 0:
            raise ValueError("Budget limit cannot be negative")
        self.limit = new_limit

    def to_dict(self) -> Dict:
        """Convert budget category to dictionary."""
        return {
            "category": self.category.value,
            "limit": self.limit,
            "spent": self.spent,
            "remaining": self.remaining,
            "utilization_percentage": self.utilization_percentage
        }


@dataclass
class User:
    """Data class representing a user in the system."""
    id: str
    name: str
    budget_categories: Dict[ExpenseCategory, BudgetCategory] = field(default_factory=dict)
    expenses: List[Expense] = field(default_factory=list)

    def add_expense(self, amount: float, category: ExpenseCategory, description: str = "") -> Expense:
        """Add an expense for this user."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive")

        # Create expense
        expense = Expense(
            id=str(uuid.uuid4()),
            user_id=self.id,
            amount=amount,
            category=category,
            description=description
        )

        # Update budget category
        if category not in self.budget_categories:
            self.budget_categories[category] = BudgetCategory(category=category, limit=0)

        self.budget_categories[category].add_expense(amount)
        self.expenses.append(expense)
        return expense

    def set_budget_limit(self, category: ExpenseCategory, limit: float) -> None:
        """Set budget limit for a specific category."""
        if limit < 0:
            raise ValueError("Budget limit cannot be negative")

        if category not in self.budget_categories:
            self.budget_categories[category] = BudgetCategory(category=category, limit=limit)
        else:
            self.budget_categories[category].adjust_limit(limit)

    def get_total_spent(self) -> float:
        """Calculate total amount spent by this user."""
        return sum(expense.amount for expense in self.expenses)

    def get_category_spent(self, category: ExpenseCategory) -> float:
        """Calculate amount spent in a specific category."""
        if category in self.budget_categories:
            return self.budget_categories[category].spent
        return 0

    def to_dict(self) -> Dict:
        """Convert user to dictionary for serialization."""
        return {
            "id": self.id,
            "name": self.name,
            "budget_categories": {
                cat.value: bc.to_dict() 
                for cat, bc in self.budget_categories.items()
            },
            "total_expenses": self.get_total_spent(),
            "expense_count": len(self.expenses)
        }


class OptimizationStrategy(ABC):
    """Abstract base class for optimization strategies."""

    @abstractmethod
    def generate_recommendations(self, users: List[User]) -> List[str]:
        """Generate optimization recommendations based on user data."""
        pass


class SpendingAnalysisStrategy(OptimizationStrategy):
    """Optimization strategy based on spending pattern analysis."""

    def generate_recommendations(self, users: List[User]) -> List[str]:
        """Generate recommendations by analyzing spending patterns."""
        recommendations = []

        if not users:
            return recommendations

        # Analyze individual spending patterns
        for user in users:
            total_spent = user.get_total_spent()
            if total_spent == 0:
                continue

            for category, budget_cat in user.budget_categories.items():
                utilization = budget_cat.utilization_percentage

                if utilization > 100:
                    recommendations.append(
                        f"User {user.name} has exceeded {category.value} budget by "
                        f"{utilization - 100:.1f}%. Consider reducing spending."
                    )
                elif utilization > 80:
                    recommendations.append(
                        f"User {user.name} is close to {category.value} budget limit "
                        f"({utilization:.1f}% used). Monitor spending carefully."
                    )

        # Compare users' spending
        avg_spending = sum(u.get_total_spent() for u in users) / len(users)
        for user in users:
            user_spending = user.get_total_spent()
            if user_spending > avg_spending * 1.5:
                recommendations.append(
                    f"User {user.name} is spending {user_spending/avg_spending:.1f}x "
                    "more than average. Consider reviewing expenses."
                )

        return recommendations


class BudgetReallocationStrategy(OptimizationStrategy):
    """Optimization strategy for budget reallocation."""

    def generate_recommendations(self, users: List[User]) -> List[str]:
        """Generate recommendations for budget reallocation."""
        recommendations = []

        if not users:
            return recommendations

        # Analyze category utilization across all users
        category_totals: Dict[ExpenseCategory, Tuple[float, float]] = {}

        for user in users:
            for category, budget_cat in user.budget_categories.items():
                if category not in category_totals:
                    category_totals[category] = (0, 0)
                spent, limit = category_totals[category]
                category_totals[category] = (spent + budget_cat.spent, limit + budget_cat.limit)

        # Find over and under utilized categories
        for category, (total_spent, total_limit) in category_totals.items():
            if total_limit > 0:
                utilization = (total_spent / total_limit) * 100

                if utilization > 120:
                    recommendations.append(
                        f"Group is overspending on {category.value} ({utilization:.1f}% of budget). "
                        "Consider reducing allocation or cutting expenses."
                    )
                elif utilization < 50:
                    recommendations.append(
                        f"Group is underspending on {category.value} ({utilization:.1f}% of budget). "
                        "Consider reallocating funds to other categories."
                    )

        return recommendations


class MultiAgentBudgetOptimizer:
    """
    Main application class for collaborative budget management.
    Manages multiple users, expenses, and provides optimization features.
