This application allows users to manage shared budgets, track expenses, and optimize spending.
"""

from typing import Dict, List, Optional, Tuple, Set
from dataclasses import dataclass, field
from enum import Enum
import json
from datetime import datetime
from abc import ABC, abstractmethod
import uuid


class ExpenseCategory(Enum):
    """Enumeration of supported expense categories."""
    GROCERIES = "Groceries"
    ENTERTAINMENT = "Entertainment"
    UTILITIES = "Utilities"
    TRANSPORTATION = "Transportation"
    DINING = "Dining"
    SHOPPING = "Shopping"
    HOUSING = "Housing"
    HEALTHCARE = "Healthcare"
    EDUCATION = "Education"
    OTHER = "Other"


@dataclass
class Expense:
    """Data class representing a single expense."""
    id: str
    user_id: str
    amount: float
    category: ExpenseCategory
    description: str
    date: datetime = field(default_factory=datetime.now)

    def to_dict(self) -> Dict:
        """Convert expense to dictionary for serialization."""
        return {
            "id": self.id,
            "user_id": self.user_id,
            "amount": self.amount,
            "category": self.category.value,
            "description": self.description,
            "date": self.date.isoformat()
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Expense':
        """Create expense from dictionary."""
        return cls(
            id=data["id"],
            user_id=data["user_id"],
            amount=data["amount"],
            category=ExpenseCategory(data["category"]),
            description=data["description"],
            date=datetime.fromisoformat(data["date"])
        )


@dataclass
class User:
    """Data class representing a user."""
    id: str
    name: str
    email: str
    expenses: List[Expense] = field(default_factory=list)

    def total_spent(self) -> float:
        """Calculate total amount spent by user."""
        return sum(expense.amount for expense in self.expenses)

    def spent_by_category(self) -> Dict[ExpenseCategory, float]:
        """Calculate spending by category."""
        result = {category: 0.0 for category in ExpenseCategory}
        for expense in self.expenses:
            result[expense.category] += expense.amount
        return result


@dataclass
class BudgetLimit:
    """Data class representing budget limit for a category."""
    category: ExpenseCategory
    limit: float

    def to_dict(self) -> Dict:
        """Convert budget limit to dictionary."""
        return {
            "category": self.category.value,
            "limit": self.limit
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'BudgetLimit':
        """Create budget limit from dictionary."""
        return cls(
            category=ExpenseCategory(data["category"]),
            limit=data["limit"]
        )


class OptimizationStrategy(ABC):
    """Abstract base class for optimization strategies."""

    @abstractmethod
    def optimize(self, 
                 users: List[User], 
                 budget_limits: List[BudgetLimit],
                 financial_goal: Optional[float] = None) -> List[str]:
        """Generate optimization suggestions."""
        pass


class ReduceHighSpendingStrategy(OptimizationStrategy):
    """Strategy that suggests reducing high spending categories."""

    def optimize(self, 
                 users: List[User], 
                 budget_limits: List[BudgetLimit],
                 financial_goal: Optional[float] = None) -> List[str]:
        suggestions = []

        # Calculate total spending by category
        category_spending = {category: 0.0 for category in ExpenseCategory}
        for user in users:
            user_spending = user.spent_by_category()
            for category, amount in user_spending.items():
                category_spending[category] += amount

        # Find budget limits
        limits_dict = {limit.category: limit.limit for limit in budget_limits}

        # Suggest reductions for categories over budget
        for category, spent in category_spending.items():
            limit = limits_dict.get(category, float('inf'))
            if spent > limit:
                overspend = spent - limit
                suggestions.append(
                    f"Reduce {category.value} spending by ${overspend:.2f} "
                    f"to stay within budget of ${limit:.2f}"
                )

        # If financial goal is set and total spending exceeds it
        if financial_goal is not None:
            total_spent = sum(category_spending.values())
            if total_spent > financial_goal:
                reduction_needed = total_spent - financial_goal
                suggestions.append(
                    f"Overall spending exceeds financial goal by "
                    f"${reduction_needed:.2f}. Consider reducing expenses."
                )

        return suggestions


class ReallocateFundsStrategy(OptimizationStrategy):
    """Strategy that suggests reallocating funds between categories."""

    def optimize(self, 
                 users: List[User], 
                 budget_limits: List[BudgetLimit],
                 financial_goal: Optional[float] = None) -> List[str]:
        suggestions = []

        # Calculate total spending by category
        category_spending = {category: 0.0 for category in ExpenseCategory}
        for user in users:
            user_spending = user.spent_by_category()
            for category, amount in user_spending.items():
                category_spending[category] += amount

        # Find budget limits
        limits_dict = {limit.category: limit.limit for limit in budget_limits}

        # Find categories under and over budget
        under_budget = []
        over_budget = []

        for category in ExpenseCategory:
            spent = category_spending[category]
            limit = limits_dict.get(category, float('inf'))
            if spent < limit * 0.8:  # Less than 80% of budget
                under_budget.append((category, limit - spent))
            elif spent > limit:
                over_budget.append((category, spent - limit))

        # Suggest reallocations
        for over_cat, over_amount in over_budget:
            for under_cat, under_amount in under_budget:
                if under_amount > 0:
                    realloc_amount = min(over_amount, under_amount)
                    if realloc_amount > 0:
                        suggestions.append(
                            f"Consider reallocating ${realloc_amount:.2f} from "
                            f"{over_cat.value} to {under_cat.value}"
                        )
                        over_amount -= realloc_amount

        return suggestions


class MultiAgentBudgetOptimizer:
    """Main class for the budget optimization system."""

    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_limits: List[BudgetLimit] = []
        self.financial_goal: Optional[float] = None
        self.optimization_strategies: List[OptimizationStrategy] = [
            ReduceHighSpendingStrategy(),
            ReallocateFundsStrategy()
        ]

    def add_user(self, name: str, email: str) -> str:
        """Add a new user and return their ID."""
        user_id = str(uuid.uuid4())
        self.users[user_id] = User(id=user_id, name=name, email=email)
        return user_id

    def get_user(self, user_id: str) -> Optional[User]:
        """Retrieve a user by ID."""
        return self.users.get(user_id)

