        """Save the current state to a JSON file."""
        state = {
            "users": [
                {
                    "id": user.id,
                    "name": user.name,
                    "budget_categories": {
                        cat.value: {
                            "limit": bc.limit,
                            "spent": bc.spent
                        }
                        for cat, bc in user.budget_categories.items()
                    },
                    "expenses": [exp.to_dict() for exp in user.expenses]
                }
                for user in self.users.values()
            ]
        }

        with open(filename, 'w') as f:
            json.dump(state, f, indent=2)

    def load_state(self, filename: str) -> None:
        """Load state from a JSON file."""
        with open(filename, 'r') as f:
            state = json.load(f)

        self.users.clear()

        for user_data in state["users"]:
            user = User(id=user_data["id"], name=user_data["name"])

            # Load budget categories
            for cat_name, cat_data in user_data["budget_categories"].items():
                category = ExpenseCategory(cat_name)
                budget_cat = BudgetCategory(
                    category=category,
                    limit=cat_data["limit"],
                    spent=cat_data["spent"]
                )
                user.budget_categories[category] = budget_cat

            # Load expenses
            for exp_data in user_data["expenses"]:
                expense = Expense.from_dict(exp_data)
                user.expenses.append(expense)

            self.users[user.id] = user


