@dataclass
class BudgetCategory:
    """Data class representing a budget category with spending limit."""
    category: ExpenseCategory = ExpenseCategory.OTHER
    limit: float = 0.0
    current_spending: float = 0.0

    def remaining(self) -> float:
        """Calculate remaining budget for this category."""
        return max(0.0, self.limit - self.current_spending)

    def percentage_used(self) -> float:
        """Calculate percentage of budget used."""
        if self.limit <= 0:
            return 0.0
        return min(100.0, (self.current_spending / self.limit) * 100)

    def to_dict(self) -> Dict[str, Any]:
        """Convert budget category to dictionary."""
        return {
            'category': self.category.value,
            'limit': self.limit,
            'current_spending': self.current_spending,
            'remaining': self.remaining(),
            'percentage_used': self.percentage_used()
        }


@dataclass
class User:
    """Data class representing a user in the system."""
    user_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    name: str = ""
    expenses: List[Expense] = field(default_factory=list)
    budget_categories: Dict[ExpenseCategory, BudgetCategory] = field(default_factory=dict)

    def add_expense(self, category: ExpenseCategory, amount: float, description: str = "") -> Expense:
        """Add a new expense for the user."""
        expense = Expense(
