            category=category,
            amount=amount,
            description=description
        )
        self.expenses.append(expense)

        # Update budget category spending
        if category in self.budget_categories:
            self.budget_categories[category].current_spending += amount

        return expense

    def set_budget_limit(self, category: ExpenseCategory, limit: float) -> BudgetCategory:
        """Set budget limit for a specific category."""
        if category not in self.budget_categories:
            self.budget_categories[category] = BudgetCategory(category=category, limit=limit)
        else:
            self.budget_categories[category].limit = limit

        # Recalculate current spending for this category
        self.budget_categories[category].current_spending = sum(
            expense.amount for expense in self.expenses 
