import os
from dotenv import load_dotenv
import json
from typing import Dict, List, Any, Optional
import logging

# Load environment variables
load_dotenv()

# Initialize Flask app
app = Flask(__name__, static_folder='../frontend/build', static_url_path='/')
app.config['SECRET_KEY'] = os.getenv('SECRET_KEY', 'cultural_connect_secret_key')
app.config['JWT_SECRET_KEY'] = os.getenv('JWT_SECRET_KEY', 'jwt_secret_key_change_in_production')
app.config['JWT_ACCESS_TOKEN_EXPIRES'] = timedelta(hours=24)
app.config['MONGO_URI'] = os.getenv('MONGO_URI', 'mongodb://localhost:27017/culturalconnect')

# Initialize extensions
CORS(app, supports_credentials=True)
bcrypt = Bcrypt(app)
jwt = JWTManager(app)
socketio = SocketIO(app, cors_allowed_origins="*", async_mode='eventlet')

# Database connection
client = MongoClient(app.config['MONGO_URI'])
db = client.culturalconnect

# Collections
users_collection = db.users
content_collection = db.cultural_content
interactions_collection = db.user_interactions
chat_messages_collection = db.chat_messages

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

