class UserModel:
    """User data model and operations"""

    @staticmethod
    def create_user(username: str, email: str, password: str, preferences: Dict = None) -> Dict:
        """Create a new user with hashed password"""
        hashed_password = bcrypt.generate_password_hash(password).decode('utf-8')

        user_data = {
            'username': username,
            'email': email,
            'password': hashed_password,
            'preferences': preferences or {
                'categories': ['literature', 'music', 'visual_arts', 'films'],
                'cultures': [],
                'languages': []
            },
            'created_at': datetime.utcnow(),
            'updated_at': datetime.utcnow(),
            'profile_picture': '',
            'bio': '',
            'is_active': True
        }

        result = users_collection.insert_one(user_data)
        user_data['_id'] = str(result.inserted_id)
        return user_data

    @staticmethod
    def authenticate_user(email: str, password: str) -> Optional[Dict]:
        """Authenticate user and return user data if valid"""
        user = users_collection.find_one({'email': email, 'is_active': True})

        if user and bcrypt.check_password_hash(user['password'], password):
            user['_id'] = str(user['_id'])
            return user
        return None

    @staticmethod
    def update_preferences(user_id: str, preferences: Dict) -> bool:
        """Update user preferences"""
        result = users_collection.update_one(
            {'_id': ObjectId(user_id)},
            {'$set': {'preferences': preferences, 'updated_at': datetime.utcnow()}}
        )
        return result.modified_count > 0

    @staticmethod
    def get_user_by_id(user_id: str) -> Optional[Dict]:
        """Get user by ID"""
        user = users_collection.find_one({'_id': ObjectId(user_id)})
        if user:
            user['_id'] = str(user['_id'])
            return user
        return None

class ContentModel:
    """Cultural content data model and operations"""

    @staticmethod
    def create_content(content_data: Dict) -> Dict:
        """Create new cultural content"""
        content_data.update({
            'created_at': datetime.utcnow(),
            'updated_at': datetime.utcnow(),
            'likes': 0,
            'shares': 0,
            'views': 0,
            'comments': [],
            'is_approved': True
        })

        result = content_collection.insert_one(content_data)
        content_data['_id'] = str(result.inserted_id)
        return content_data

    @staticmethod
    def get_content_by_category(category: str, limit: int = 20, skip: int = 0) -> List[Dict]:
        """Get content by category with pagination"""
        content = list(content_collection.find(
            {'category': category, 'is_approved': True}
        ).skip(skip).limit(limit))

        for item in content:
            item['_id'] = str(item['_id'])
        return content

    @staticmethod
    def search_content(query: str, categories: List[str] = None) -> List[Dict]:
        """Search content by query and optional categories"""
        search_filter = {
            '$or': [
                {'title': {'$regex': query, '$options': 'i'}},
                {'description': {'$regex': query, '$options': 'i'}},
                {'tags': {'$regex': query, '$options': 'i'}}
            ],
            'is_approved': True
        }

        if categories:
            search_filter['category'] = {'$in': categories}

        content = list(content_collection.find(search_filter).limit(50))

        for item in content:
            item['_id'] = str(item['_id'])
        return content

    @staticmethod
    def increment_interaction(content_id: str, interaction_type: str) -> bool:
        """Increment content interactions (views, likes, shares)"""
        increment_field = f"{interaction_type}s"
        result = content_collection.update_one(
            {'_id': ObjectId(content_id)},
            {'$inc': {increment_field: 1}}
        )
        return result.modified_count > 0

class RecommendationSystem:
    """Content recommendation engine"""

    @staticmethod
    def get_recommendations(user_id: str, limit: int = 10) -> List[Dict]:
        """Get personalized content recommendations for user"""
        # Get user preferences
        user = users_collection.find_one({'_id': ObjectId(user_id)})
        if not user:
            return []

        preferences = user.get('preferences', {})
        categories = preferences.get('categories', [])
        cultures = preferences.get('cultures', [])

        # Get user interaction history
        interactions = list(interactions_collection.find(
            {'user_id': user_id, 'interaction_type': 'view'}
        ).sort('timestamp', -1).limit(50))

        # Content-based filtering
        query_filter = {
            'is_approved': True,
            '$or': []
        }

        # Add category filter
        if categories:
            query_filter['$or'].append({'category': {'$in': categories}})

        # Add culture filter
        if cultures:
            query_filter['$or'].append({'culture': {'$in': cultures}})

        # If user has interactions, add content similarity
        if interactions:
            viewed_content_ids = [i['content_id'] for i in interactions]
            similar_content = content_collection.find({
                'tags': {'$in': get_common_tags(viewed_content_ids)},
                'is_approved': True
            }).limit(limit)

            content = list(similar_content)
        else:
            # Fallback to popular content
            content = list(content_collection.find(
                {'is_approved': True}
            ).sort('views', -1).limit(limit))

        for item in content:
            item['_id'] = str(item['_id'])
        return content

    @staticmethod
    def record_interaction(user_id: str, content_id: str, interaction_type: str):
        """Record user interaction for recommendation training"""
        interaction = {
            'user_id': user_id,
            'content_id': content_id,
            'interaction_type': interaction_type,
            'timestamp': datetime.utcnow()
        }
        interactions_collection.insert_one(interaction)

def get_common_tags(content_ids: List[str]) -> List[str]:
    """Get common tags from content for similarity calculation"""
    content_tags = []
    for content_id in content_ids[:10]:  # Limit to recent 10
        content = content_collection.find_one({'_id': ObjectId(content_id)})
        if content and 'tags' in content:
            content_tags.extend(content['tags'])

    # Return most common tags
    from collections import Counter
    tag_counter = Counter(content_tags)
    return [tag for tag, count in tag_counter.most_common(5)]

