@app.route('/api/content', methods=['GET'])
def get_content():
    """Get cultural content with filtering"""
    try:
        category = request.args.get('category', 'all')
        page = int(request.args.get('page', 1))
        limit = int(request.args.get('limit', 20))
        skip = (page - 1) * limit

        if category == 'all':
            content = list(content_collection.find({'is_approved': True})
                          .skip(skip).limit(limit))
        else:
            content = ContentModel.get_content_by_category(category, limit, skip)

        total = content_collection.count_documents({'is_approved': True})

        return jsonify({
            'content': content,
            'pagination': {
                'page': page,
                'limit': limit,
                'total': total,
                'pages': (total + limit - 1) // limit
            }
        }), 200

    except Exception as e:
        logger.error(f"Content error: {str(e)}")
        return jsonify({'error': 'Internal server error'}), 500

