@socketio.on('disconnect')
def handle_disconnect():
    """Handle user disconnection"""
    try:
        if request.sid in connected_users:
            user_info = connected_users[request.sid]

            # Broadcast user offline status
            broadcast_user_status(user_info['user_id'], user_info['username'], 'offline')

            # Leave all rooms
            for room_id in list(user_info['rooms']):
                leave_room(room_id)
                emit('user_left', {
                    'user_id': user_info['user_id'],
                    'username': user_info['username'],
                    'room_id': room_id,
                    'timestamp': datetime.utcnow().isoformat()
                }, room=room_id)

            # Remove from connected users
            del connected_users[request.sid]

            logger.info(f"User disconnected: {user_info['username']} ({user_info['user_id']})")
        else:
            logger.info(f"Anonymous client disconnected: {request.sid}")

    except Exception as e:
        logger.error(f"Disconnect error: {str(e)}")


