class ComplexityLevel(Enum):
    CONSTANT = "O(1)"
    LOGARITHMIC = "O(log n)"
    LINEAR = "O(n)"
    LOG_LINEAR = "O(n log n)"
    QUADRATIC = "O(n²)"
    CUBIC = "O(n³)"
