@dataclass
class EfficiencyMetrics:
    time_complexity: ComplexityLevel
    space_complexity: ComplexityLevel
    cyclomatic_complexity: int
    lines_of_code: int
    issues: List[CodeIssue]

class ComplexityAnalyzer:
    @staticmethod
    def analyze_time_complexity(code_snippet: str) -> ComplexityLevel:
        """Analyze time complexity based on patterns in code"""
        code_lower = code_snippet.lower()

        if 'for i in range' in code_lower and 'for j in range' in code_lower:
            if 'for k in range' in code_lower:
                return ComplexityLevel.CUBIC
            return ComplexityLevel.QUADRATIC
        elif 'for ' in code_lower and 'while ' in code_lower:
            return ComplexityLevel.LOG_LINEAR
        elif 'for ' in code_lower or 'while ' in code_lower:
            return ComplexityLevel.LINEAR
        elif 'binary' in code_lower or 'search' in code_lower:
            return ComplexityLevel.LOGARITHMIC
        else:
            return ComplexityLevel.CONSTANT

    @staticmethod
    def analyze_space_complexity(code_snippet: str) -> ComplexityLevel:
        """Analyze space complexity based on data structures used"""
        code_lower = code_snippet.lower()

        if 'list(' in code_lower or 'dict(' in code_lower or 'set(' in code_lower:
            if 'for ' in code_lower:
                return ComplexityLevel.LINEAR
        return ComplexityLevel.CONSTANT

class CodeEfficiencyAnalyzer:
    def __init__(self):
        self.complexity_analyzer = ComplexityAnalyzer()

    def analyze_code(self, code_snippet: str) -> EfficiencyMetrics:
        """Analyze code efficiency and return metrics"""
        issues = self._detect_issues(code_snippet)

        metrics = EfficiencyMetrics(
            time_complexity=self.complexity_analyzer.analyze_time_complexity(code_snippet),
            space_complexity=self.complexity_analyzer.analyze_space_complexity(code_snippet),
            cyclomatic_complexity=self._calculate_cyclomatic_complexity(code_snippet),
            lines_of_code=len(code_snippet.split('\n')),
            issues=issues
        )

        return metrics

    def _detect_issues(self, code_snippet: str) -> List[CodeIssue]:
        """Detect common code inefficiencies"""
        issues = []
        lines = code_snippet.split('\n')

        for i, line in enumerate(lines, 1):
            line_stripped = line.strip()

            # Detect nested loops
            if 'for ' in line_stripped and 'range' in line_stripped:
                if i > 1 and 'for ' in lines[i-2].strip():
                    issues.append(CodeIssue(
                        line_number=i,
                        issue_type="NESTED_LOOP",
                        description="Potential nested loop detected",
                        severity="MEDIUM",
                        recommendation="Consider using more efficient algorithms or data structures"
                    ))

            # Detect expensive operations inside loops
            if 'for ' in line_stripped or 'while ' in line_stripped:
                if i < len(lines) and ('list(' in lines[i] or 'sorted(' in lines[i]):
                    issues.append(CodeIssue(
                        line_number=i+1,
                        issue_type="EXPENSIVE_OPERATION_IN_LOOP",
                        description="Expensive operation inside loop",
                        severity="HIGH",
                        recommendation="Move expensive operations outside the loop if possible"
                    ))

            # Detect unused variables
            if '=' in line_stripped and not line_stripped.startswith('#'):
                var_name = line_stripped.split('=')[0].strip()
                if var_name and var_name not in code_snippet[i*10:]:  # Simple check
                    issues.append(CodeIssue(
                        line_number=i,
                        issue_type="UNUSED_VARIABLE",
                        description=f"Variable '{var_name}' may be unused",
                        severity="LOW",
                        recommendation="Remove unused variables to improve code clarity"
                    ))

        return issues

    def _calculate_cyclomatic_complexity(self, code_snippet: str) -> int:
        """Calculate cyclomatic complexity"""
        complexity = 1  # Base complexity
        keywords = ['if', 'elif', 'for', 'while', 'and', 'or']

        for keyword in keywords:
            complexity += code_snippet.lower().count(f' {keyword} ')

        return complexity

    def get_optimization_recommendations(self, metrics: EfficiencyMetrics) -> List[str]:
        """Generate optimization recommendations based on metrics"""
        recommendations = []

        if metrics.time_complexity in [ComplexityLevel.QUADRATIC, ComplexityLevel.CUBIC, ComplexityLevel.EXPONENTIAL]:
            recommendations.append(f"Consider optimizing from {metrics.time_complexity.value} to O(n log n) or better")

        if metrics.cyclomatic_complexity > 10:
            recommendations.append(f"Cyclomatic complexity ({metrics.cyclomatic_complexity}) is high. Consider refactoring into smaller functions")

        for issue in metrics.issues:
            if issue.severity in ["HIGH", "MEDIUM"]:
                recommendations.append(f"Line {issue.line_number}: {issue.recommendation}")

        return recommendations


