    def to_dict(self) -> Dict:
        """Convert user to dictionary for serialization"""
        data = asdict(self)
        data['created_at'] = self.created_at.isoformat()
        return data

    @classmethod
    def from_dict(cls, data: Dict) -> 'User':
        """Create user from dictionary"""
        data['created_at'] = datetime.fromisoformat(data['created_at'])
        return cls(**data)

@dataclass
class Contribution:
    """Individual contribution from a user"""
    contribution_id: str
    user_id: str
    amount: float
    timestamp: datetime = field(default_factory=datetime.now)
    description: str = ""

    def to_dict(self) -> Dict:
        """Convert contribution to dictionary"""
        data = asdict(self)
        data['timestamp'] = self.timestamp.isoformat()
        return data

    @classmethod
    def from_dict(cls, data: Dict) -> 'Contribution':
        """Create contribution from dictionary"""
        data['timestamp'] = datetime.fromisoformat(data['timestamp'])
        return cls(**data)

@dataclass
class Milestone:
    """Milestone for tracking progress"""
    milestone_id: str
    name: str
    target_amount: float
    deadline: datetime
    achieved: bool = False
    achieved_at: Optional[datetime] = None

    def to_dict(self) -> Dict:
        """Convert milestone to dictionary"""
        data = asdict(self)
        data['deadline'] = self.deadline.isoformat()
        if self.achieved_at:
            data['achieved_at'] = self.achieved_at.isoformat()
        return data

    @classmethod
    def from_dict(cls, data: Dict) -> 'Milestone':
        """Create milestone from dictionary"""
        data['deadline'] = datetime.fromisoformat(data['deadline'])
        if data.get('achieved_at'):
            data['achieved_at'] = datetime.fromisoformat(data['achieved_at'])
        return cls(**data)

@dataclass
class Goal:
    """Financial goal for a group"""
    goal_id: str
    name: str
    target_amount: float
    deadline: datetime
    created_at: datetime = field(default_factory=datetime.now)
    contributions: List[Contribution] = field(default_factory=list)
    milestones: List[Milestone] = field(default_factory=list)

    @property
    def total_contributed(self) -> float:
        """Calculate total contributions"""
        return sum(c.amount for c in self.contributions)

    @property
    def remaining_amount(self) -> float:
        """Calculate remaining amount to reach goal"""
        return max(0, self.target_amount - self.total_contributed)

    @property
    def progress_percentage(self) -> float:
        """Calculate progress percentage"""
        if self.target_amount == 0:
            return 0.0
        return min(100.0, (self.total_contributed / self.target_amount) * 100)

