            name=name,
            description=description,
            admin_id=admin_id
        )
        group.members.add(admin_id)

        # Save group
        if self.storage.save_group(group):
            return True, "Group created successfully", group

        return False, "Failed to create group", None

    def join_group(self, group_id: str, user_id: str) -> Tuple[bool, str]:
        """Add user to group"""
        group = self.storage.get_group(group_id)
        if not group:
            return False, "Group not found"

        user = self.storage.get_user(user_id)
        if not user:
            return False, "User not found"

        if user_id in group.members:
            return False, "User already in group"

        group.members.add(user_id)
        if self.storage.save_group(group):
            return True, "Joined group successfully"

        return False, "Failed to join group"

    def leave_group(self, group_id: str, user_id: str) -> Tuple[bool, str]:
        """Remove user from group"""
        group = self.storage.get_group(group_id)
        if not group:
            return False, "Group not found"

        if user_id not in group.members:
            return False, "User not in group"

        # Admin cannot leave group without transferring admin rights
        if user_id == group.admin_id:
            return False, "Admin cannot leave group. Transfer admin rights first."

        group.members.remove(user_id)
        if self.storage.save_group(group):
            return True, "Left group successfully"

        return False, "Failed to leave group"

