class JSONStorage(Storage):
    """JSON file-based storage implementation"""

    def __init__(self, filename: str = "financial_collaborator_data.json"):
        self.filename = filename
        self.lock = threading.Lock()
        self._load_data()

    def _load_data(self):
        """Load data from JSON file"""
        try:
            with open(self.filename, 'r') as f:
                data = json.load(f)
                self.users = {uid: User.from_dict(u) for uid, u in data.get('users', {}).items()}
                self.groups = {gid: Group.from_dict(g) for gid, g in data.get('groups', {}).items()}
                self.notifications = {nid: Notification.from_dict(n) for nid, n in data.get('notifications', {}).items()}
        except FileNotFoundError:
            self.users = {}
            self.groups = {}
            self.notifications = {}

    def _save_data(self):
        """Save data to JSON file"""
        with self.lock:
            data = {
                'users': {uid: u.to_dict() for uid, u in self.users.items()},
                'groups': {gid: g.to_dict() for gid, g in self.groups.items()},
                'notifications': {nid: n.to_dict() for nid, n in self.notifications.items()}
            }
            with open(self.filename, 'w') as f:
                json.dump(data, f, indent=2)

    def save_user(self, user: User) -> bool:
        self.users[user.user_id] = user
        self._save_data()
        return True

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def get_user_by_username(self, username: str) -> Optional[User]:
        for user in self.users.values():
            if user.username == username:
                return user
        return None

    def get_user_by_email(self, email: str) -> Optional[User]:
        for user in self.users.values():
            if user.email == email:
                return user
        return None

    def save_group(self, group: Group) -> bool:
        self.groups[group.group_id] = group
        self._save_data()
        return True

    def get_group(self, group_id: str) -> Optional[Group]:
        return self.groups.get(group_id)

    def get_user_groups(self, user_id: str) -> List[Group]:
        user_groups = []
        for group in self.groups.values():
            if user_id in group.members:
                user_groups.append(group)
        return user_groups

    def save_notification(self, notification: Notification) -> bool:
        self.notifications[notification.notification_id] = notification
        self._save_data()
        return True

    def get_user_notifications(self, user_id: str) -> List[Notification]:
        user_notifications = []
        for notification in self.notifications.values():
            if notification.user_id == user_id:
                user_notifications.append(notification)
        return sorted(user_notifications, key=lambda x: x.timestamp, reverse=True)

    def mark_notification_read(self, notification_id: str) -> bool:
        if notification_id in self.notifications:
            self.notifications[notification_id].read = True
            self._save_data()
            return True
        return False

