class AuthenticationService:
    """Handles user authentication and registration"""

    def __init__(self, storage: Storage):
        self.storage = storage

    def hash_password(self, password: str) -> str:
        """Hash password using SHA-256"""
        return hashlib.sha256(password.encode()).hexdigest()

    def register_user(self, username: str, email: str, password: str) -> Tuple[bool, str, Optional[User]]:
        """Register a new user"""
        # Check for duplicate username
        if self.storage.get_user_by_username(username):
            return False, "Username already exists", None

        # Check for duplicate email
        if self.storage.get_user_by_email(email):
            return False, "Email already registered", None

        # Validate inputs
        if not username or not email or not password:
            return False, "All fields are required", None

        if len(password) < 6:
            return False, "Password must be at least 6 characters", None

        # Create new user
        user_id = str(uuid.uuid4())
        password_hash = self.hash_password(password)
        user = User(
            user_id=user_id,
            username=username,
            email=email,
            password_hash=password_hash
        )

        # Save user
        if self.storage.save_user(user):
            return True, "Registration successful", user

        return False, "Registration failed", None

    def login(self, username: str, password: str) -> Tuple[bool, str, Optional[User]]:
        """Authenticate user"""
        user = self.storage.get_user_by_username(username)
        if not user:
            return False, "User not found", None

        password_hash = self.hash_password(password)
        if user.password_hash == password_hash:
            return True, "Login successful", user

        return False, "Invalid password", None

