# solution.py

import json
import random
import datetime
from abc import ABC, abstractmethod
from typing import Dict, List, Tuple, Optional, Any
from dataclasses import dataclass, asdict
from enum import Enum


# ==================== Data Models ====================

class Difficulty(Enum):
    """Enum representing difficulty levels."""
    BEGINNER = "beginner"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"


class Language(Enum):
    """Enum representing supported languages."""
    ENGLISH = "english"
    SPANISH = "spanish"
    FRENCH = "french"
    GERMAN = "german"


@dataclass
class UserProgress:
    """Data class to track user progress."""
    user_id: str
    language: Language
    difficulty: Difficulty
    vocabulary_scores: List[Dict[str, Any]]  # List of {'date': str, 'score': int}
    grammar_scores: List[Dict[str, Any]]
    comprehension_scores: List[Dict[str, Any]]
    total_exercises_completed: int = 0

    def add_score(self, module: str, score: int) -> None:
        """Add a score for a specific module."""
        score_record = {
            'date': datetime.datetime.now().isoformat(),
            'score': score
        }

        if module == 'vocabulary':
            self.vocabulary_scores.append(score_record)
        elif module == 'grammar':
            self.grammar_scores.append(score_record)
        elif module == 'comprehension':
            self.comprehension_scores.append(score_record)

        self.total_exercises_completed += 1

    def get_average_score(self, module: str) -> float:
        """Calculate average score for a specific module."""
        scores = []
        if module == 'vocabulary':
            scores = [s['score'] for s in self.vocabulary_scores]
        elif module == 'grammar':
            scores = [s['score'] for s in self.grammar_scores]
        elif module == 'comprehension':
            scores = [s['score'] for s in self.comprehension_scores]

        return sum(scores) / len(scores) if scores else 0.0

    def to_dict(self) -> Dict[str, Any]:
        """Convert UserProgress to dictionary for serialization."""
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'UserProgress':
        """Create UserProgress instance from dictionary."""
        # Convert string enums back to Enum instances
        data['language'] = Language(data['language'])
        data['difficulty'] = Difficulty(data['difficulty'])
        return cls(**data)


# ==================== Base Classes ====================

class Exercise(ABC):
    """Abstract base class for all exercises."""

    def __init__(self, language: Language, difficulty: Difficulty):
        self.language = language
        self.difficulty = difficulty

    @abstractmethod
    def generate_question(self) -> Tuple[str, List[str], str]:
        """Generate a question, options, and correct answer."""
        pass

    @abstractmethod
    def validate_answer(self, user_answer: str, correct_answer: str) -> bool:
        """Validate user's answer."""
        pass


# ==================== Vocabulary Module ====================

class VocabularyExercise(Exercise):
    """Vocabulary exercises including flashcards, multiple-choice, and fill-in-the-blank."""

    # Vocabulary data structure: word -> translation
    VOCABULARY_DATA = {
        Language.ENGLISH: {
            Difficulty.BEGINNER: {
                'hello': 'hola', 'goodbye': 'adiós', 'thank you': 'gracias',
                'please': 'por favor', 'yes': 'sí', 'no': 'no'
            },
            Difficulty.INTERMEDIATE: {
                'beautiful': 'hermoso', 'difficult': 'difícil',
                'interesting': 'interesante', 'important': 'importante'
            },
            Difficulty.ADVANCED: {
                'perseverance': 'perseverancia', 'ambiguity': 'ambigüedad',
                'sophisticated': 'sofisticado'
            }
        },
        Language.SPANISH: {
            Difficulty.BEGINNER: {
                'hola': 'hello', 'adiós': 'goodbye', 'gracias': 'thank you'
            }
        }
    }

    def __init__(self, language: Language, difficulty: Difficulty, exercise_type: str = 'flashcard'):
        super().__init__(language, difficulty)
        self.exercise_type = exercise_type
        self.words = self._get_words()

    def _get_words(self) -> List[str]:
        """Get words for the selected language and difficulty."""
        if self.language in self.VOCABULARY_DATA:
            if self.difficulty in self.VOCABULARY_DATA[self.language]:
                return list(self.VOCABULARY_DATA[self.language][self.difficulty].keys())
        return []

    def generate_question(self) -> Tuple[str, List[str], str]:
        """Generate vocabulary question based on exercise type."""
        if not self.words:
            return "No vocabulary available for this language/difficulty.", [], ""

        word = random.choice(self.words)
        translation = self.VOCABULARY_DATA[self.language][self.difficulty][word]

        if self.exercise_type == 'flashcard':
            question = f"What is the translation of '{word}'?"
            options = [translation]
        elif self.exercise_type == 'multiple_choice':
            question = f"What is the translation of '{word}'?"
            # Generate 3 wrong options
            all_translations = list(self.VOCABULARY_DATA[self.language][self.difficulty].values())
            wrong_options = [t for t in all_translations if t != translation]
            wrong_options = random.sample(wrong_options, min(3, len(wrong_options)))
            options = [translation] + wrong_options
            random.shuffle(options)
        elif self.exercise_type == 'fill_blank':
            question = f"Fill in the blank: '{word}' means ________."
            options = [translation]
        else:
            question = f"What is the translation of '{word}'?"
            options = [translation]

        return question, options, translation

    def validate_answer(self, user_answer: str, correct_answer: str) -> bool:
        """Validate vocabulary answer (case-insensitive)."""
        return user_answer.strip().lower() == correct_answer.lower()


# ==================== Grammar Module ====================

class GrammarExercise(Exercise):
    """Grammar exercises covering verb tenses, sentence structure, and parts of speech."""

    GRAMMAR_DATA = {
        Language.ENGLISH: {
            Difficulty.BEGINNER: [
                {
                    'question': 'What is the past tense of "go"?',
                    'options': ['went', 'goed', 'going', 'gone'],
                    'answer': 'went'
                },
                {
                    'question': 'Which word is a noun in: "The cat sleeps"?',
                    'options': ['The', 'cat', 'sleeps'],
                    'answer': 'cat'
                }
            ],
            Difficulty.INTERMEDIATE: [
                {
                    'question': 'Complete: "If I ___ you, I would study more."',
                    'options': ['was', 'were', 'am', 'be'],
                    'answer': 'were'
                }
            ]
        }
    }

    def generate_question(self) -> Tuple[str, List[str], str]:
        """Generate grammar question."""
        if (self.language in self.GRAMMAR_DATA and 
            self.difficulty in self.GRAMMAR_DATA[self.language]):
            questions = self.GRAMMAR_DATA[self.language][self.difficulty]
            if questions:
                q = random.choice(questions)
                return q['question'], q['options'], q['answer']

        return "No grammar questions available.", [], ""

    def validate_answer(self, user_answer: str, correct_answer: str) -> bool:
        """Validate grammar answer."""
        return user_answer.strip().lower() == correct_answer.lower()


# ==================== Comprehension Module ====================

class ComprehensionExercise(Exercise):
    """Reading comprehension exercises with passages and questions."""

    COMPREHENSION_DATA = {
        Language.ENGLISH: {
            Difficulty.BEGINNER: {
                'passage': 'The sun is bright. The sky is blue. Birds fly high.',
                'questions': [
                    {
                        'question': 'What is bright?',
                        'options': ['The sun', 'The sky', 'Birds'],
                        'answer': 'The sun'
                    },
                    {
                        'question': 'What color is the sky?',
                        'options': ['Blue', 'Red', 'Green'],
                        'answer': 'Blue'
                    }
                ]
            },
            Difficulty.INTERMEDIATE: {
                'passage': 'Global warming is a serious issue affecting our planet. Rising temperatures cause ice caps to melt and sea levels to rise.',
                'questions': [
                    {
                        'question': 'What is the main topic?',
                        'options': ['Global warming', 'Ice caps', 'Sea levels'],
                        'answer': 'Global warming'
                    }
                ]
            }
        }
    }

    def __init__(self, language: Language, difficulty: Difficulty):
        super().__init__(language, difficulty)
        self.current_question_index = 0
        self.questions = self._get_questions()

    def _get_questions(self) -> List[Dict[str, Any]]:
        """Get questions for the selected language and difficulty."""
        if (self.language in self.COMPREHENSION_DATA and 
            self.difficulty in self.COMPREHENSION_DATA[self.language]):
            return self.COMPREHENSION_DATA[self.language][self.difficulty]['questions']
        return []

    def get_passage(self) -> str:
        """Get the reading passage."""
        if (self.language in self.COMPREHENSION_DATA and 
            self.difficulty in self.COMPREHENSION_DATA[self.language]):
            return self.COMPREHENSION_DATA[self.language][self.difficulty]['passage']
        return "No passage available."

    def generate_question(self) -> Tuple[str, List[str], str]:
        """Generate comprehension question."""
        if self.current_question_index < len(self.questions):
            q = self.questions[self.current_question_index]
            self.current_question_index += 1
            return q['question'], q['options'], q['answer']

        return "No more questions.", [], ""

