# ==================== Data Models ====================

class Difficulty(Enum):
    """Enum representing difficulty levels."""
    BEGINNER = "beginner"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"


class Language(Enum):
    """Enum representing supported languages."""
    ENGLISH = "english"
    SPANISH = "spanish"
    FRENCH = "french"
    GERMAN = "german"


@dataclass
class UserProgress:
    """Data class to track user progress."""
    user_id: str
    language: Language
    difficulty: Difficulty
    vocabulary_scores: List[Dict[str, Any]]  # List of {'date': str, 'score': int}
    grammar_scores: List[Dict[str, Any]]
    comprehension_scores: List[Dict[str, Any]]
    total_exercises_completed: int = 0

    def add_score(self, module: str, score: int) -> None:
        """Add a score for a specific module."""
        score_record = {
            'date': datetime.datetime.now().isoformat(),
            'score': score
        }

        if module == 'vocabulary':
            self.vocabulary_scores.append(score_record)
        elif module == 'grammar':
            self.grammar_scores.append(score_record)
        elif module == 'comprehension':
            self.comprehension_scores.append(score_record)

        self.total_exercises_completed += 1

    def get_average_score(self, module: str) -> float:
        """Calculate average score for a specific module."""
        scores = []
        if module == 'vocabulary':
            scores = [s['score'] for s in self.vocabulary_scores]
        elif module == 'grammar':
            scores = [s['score'] for s in self.grammar_scores]
        elif module == 'comprehension':
            scores = [s['score'] for s in self.comprehension_scores]

        return sum(scores) / len(scores) if scores else 0.0

    def to_dict(self) -> Dict[str, Any]:
        """Convert UserProgress to dictionary for serialization."""
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'UserProgress':
        """Create UserProgress instance from dictionary."""
        # Convert string enums back to Enum instances
        data['language'] = Language(data['language'])
        data['difficulty'] = Difficulty(data['difficulty'])
