                'hello': 'hola', 'goodbye': 'adiós', 'thank you': 'gracias',
                'please': 'por favor', 'yes': 'sí', 'no': 'no'
            },
            Difficulty.INTERMEDIATE: {
                'beautiful': 'hermoso', 'difficult': 'difícil',
                'interesting': 'interesante', 'important': 'importante'
            },
