    def _get_words(self) -> List[str]:
        """Get words for the selected language and difficulty."""
        if self.language in self.VOCABULARY_DATA:
            if self.difficulty in self.VOCABULARY_DATA[self.language]:
                return list(self.VOCABULARY_DATA[self.language][self.difficulty].keys())
        return []

    def generate_question(self) -> Tuple[str, List[str], str]:
        """Generate vocabulary question based on exercise type."""
        if not self.words:
            return "No vocabulary available for this language/difficulty.", [], ""

        word = random.choice(self.words)
        translation = self.VOCABULARY_DATA[self.language][self.difficulty][word]

        if self.exercise_type == 'flashcard':
            question = f"What is the translation of '{word}'?"
            options = [translation]
        elif self.exercise_type == 'multiple_choice':
            question = f"What is the translation of '{word}'?"
            # Generate 3 wrong options
            all_translations = list(self.VOCABULARY_DATA[self.language][self.difficulty].values())
            wrong_options = [t for t in all_translations if t != translation]
            wrong_options = random.sample(wrong_options, min(3, len(wrong_options)))
            options = [translation] + wrong_options
            random.shuffle(options)
