# ==================== Progress Tracking ====================

class ProgressTracker:
    """Manages user progress and analytics."""

    def __init__(self, storage_file: str = 'user_progress.json'):
        self.storage_file = storage_file
        self.users: Dict[str, UserProgress] = {}
        self.load_progress()

    def register_user(self, user_id: str, language: Language, difficulty: Difficulty) -> None:
        """Register a new user."""
        if user_id not in self.users:
            self.users[user_id] = UserProgress(
                user_id=user_id,
                language=language,
                difficulty=difficulty,
                vocabulary_scores=[],
                grammar_scores=[],
                comprehension_scores=[]
            )
            self.save_progress()

    def update_score(self, user_id: str, module: str, score: int) -> None:
        """Update user's score for a module."""
        if user_id in self.users:
            self.users[user_id].add_score(module, score)
            self.save_progress()

    def get_user_progress(self, user_id: str) -> Optional[UserProgress]:
        """Get user's progress."""
        return self.users.get(user_id)

    def get_analytics(self, user_id: str) -> Dict[str, Any]:
        """Get analytics for a user."""
        if user_id not in self.users:
            return {}

        user = self.users[user_id]
        return {
            'user_id': user_id,
            'language': user.language.value,
            'difficulty': user.difficulty.value,
            'total_exercises': user.total_exercises_completed,
            'vocabulary_avg': user.get_average_score('vocabulary'),
            'grammar_avg': user.get_average_score('grammar'),
            'comprehension_avg': user.get_average_score('comprehension'),
            'overall_avg': (user.get_average_score('vocabulary') + 
                          user.get_average_score('grammar') + 
                          user.get_average_score('comprehension')) / 3
        }

    def save_progress(self) -> None:
        """Save progress to file."""
        data = {user_id: user.to_dict() for user_id, user in self.users.items()}
        with open(self.storage_file, 'w') as f:
            json.dump(data, f, indent=2)

    def load_progress(self) -> None:
        """Load progress from file."""
        try:
            with open(self.storage_file, 'r') as f:
                data = json.load(f)
                for user_id, user_data in data.items():
                    self.users[user_id] = UserProgress.from_dict(user_data)
        except FileNotFoundError:
            self.users = {}


