# ==================== Data Models ====================

class Difficulty(Enum):
    """Enum representing difficulty levels."""
    BEGINNER = "beginner"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"


class Language(Enum):
    """Enum representing supported languages."""
    ENGLISH = "english"
    SPANISH = "spanish"
    FRENCH = "french"
    GERMAN = "german"
    JAPANESE = "japanese"


@dataclass
class ProgressData:
    """Data class for tracking user progress."""
    user_id: str
    language: str
    difficulty: str
    vocabulary_scores: List[int] = None
    grammar_scores: List[int] = None
    comprehension_scores: List[int] = None
    last_session: str = None
    total_sessions: int = 0
    average_score: float = 0.0

    def __post_init__(self):
        if self.vocabulary_scores is None:
            self.vocabulary_scores = []
        if self.grammar_scores is None:
            self.grammar_scores = []
        if self.comprehension_scores is None:
            self.comprehension_scores = []

    def update_average(self):
        """Update the average score."""
        all_scores = self.vocabulary_scores + self.grammar_scores + self.comprehension_scores
        if all_scores:
            self.average_score = sum(all_scores) / len(all_scores)
        else:
            self.average_score = 0.0


@dataclass
class ExerciseResult:
    """Data class for exercise results."""
    score: int
    total_questions: int
