    @abstractmethod
    def evaluate_answer(self, question: Dict[str, Any], user_answer: str) -> bool:
        """Evaluate user's answer."""
        pass

    def get_feedback(self, question: Dict[str, Any], is_correct: bool) -> str:
        """Provide feedback for the answer."""
        if is_correct:
            return random.choice(["Excellent!", "Well done!", "Correct!", "Perfect!"]) + " " + question.get('explanation', '')
        else:
            return f"Incorrect. The right answer is: {question.get('correct_answer', 'N/A')}. " + question.get('explanation', '')


# ==================== Vocabulary Module ====================

class VocabularyExercise(Exercise):
    """Vocabulary exercise module."""

