                    {"word": "thank you", "translation": "gracias", "example": "Thank you for your help.", "type": "expression"},
                ],
                Difficulty.INTERMEDIATE: [
                    {"word": "determination", "translation": "determinación", "example": "Her determination helped her succeed.", "type": "noun"},
