                    {"word": "ephemeral", "translation": "efímero", "example": "The beauty of cherry blossoms is ephemeral.", "type": "adjective"},
                ]
            }
        }

        # Add more languages in a real implementation
        if self.language in words_data and self.difficulty in words_data[self.language]:
            return words_data[self.language][self.difficulty]
        return []

    def generate_questions(self, count: int) -> List[Dict[str, Any]]:
        """Generate vocabulary questions."""
        if not self.words:
            return []

        questions = []
        for _ in range(min(count, len(self.words))):
            word = random.choice(self.words)
            question_type = random.choice(["flashcard", "multiple_choice", "fill_blank"])

            if question_type == "flashcard":
                questions.append({
                    "type": "flashcard",
                    "prompt": f"Translate: {word['word']}",
                    "correct_answer": word['translation'],
                    "explanation": f"{word['word']} means {word['translation']}. Example: {word['example']}",
                    "word": word
                })
            elif question_type == "multiple_choice":
                wrong_answers = [w['translation'] for w in self.words if w['translation'] != word['translation']]
                options = [word['translation']] + random.sample(wrong_answers, min(3, len(wrong_answers)))
                random.shuffle(options)

                questions.append({
                    "type": "multiple_choice",
                    "prompt": f"What is the translation of '{word['word']}'?",
                    "options": options,
                    "correct_answer": word['translation'],
                    "explanation": f"{word['word']} means {word['translation']}. Example: {word['example']}",
                    "word": word
                })
            else:  # fill_blank
                example = word['example'].replace(word['word'], "_____")
                questions.append({
                    "type": "fill_blank",
                    "prompt": f"Fill in the blank: {example}",
                    "correct_answer": word['word'],
                    "explanation": f"The correct word is '{word['word']}' which means {word['translation']}.",
                    "word": word
                })

        return questions

    def evaluate_answer(self, question: Dict[str, Any], user_answer: str) -> bool:
        """Evaluate vocabulary answer."""
        correct_answer = question['correct_answer']

