# ==================== NLP PROCESSOR INTERFACE ====================

class NLPProcessor(ABC):
    @abstractmethod
    def summarize(self, text: str, max_length: int = 150) -> str:
        pass

    @abstractmethod
    def categorize(self, text: str) -> NewsCategory:
        pass

    @abstractmethod
    def analyze_sentiment(self, text: str) -> Sentiment:
        pass

    @abstractmethod
    def extract_keywords(self, text: str, num_keywords: int = 5) -> List[str]:
        pass

# ==================== SIMPLE NLP PROCESSOR ====================

class SimpleNLPProcessor(NLPProcessor):
    def summarize(self, text: str, max_length: int = 150) -> str:
        sentences = text.split('. ')
        if len(sentences) > 1:
            summary = '. '.join(sentences[:2]) + '.'
        else:
            summary = text[:max_length]
        return summary if len(summary) <= max_length else summary[:max_length-3] + '...'

    def categorize(self, text: str) -> NewsCategory:
        text_lower = text.lower()
        category_keywords = {
            NewsCategory.POLITICS: ['election', 'government', 'president', 'senate', 'congress'],
            NewsCategory.TECHNOLOGY: ['technology', 'software', 'ai', 'computer', 'digital'],
            NewsCategory.HEALTH: ['health', 'medical', 'hospital', 'doctor', 'vaccine'],
            NewsCategory.BUSINESS: ['business', 'market', 'stock', 'economy', 'company'],
            NewsCategory.SPORTS: ['sports', 'game', 'team', 'player', 'championship'],
            NewsCategory.ENTERTAINMENT: ['movie', 'celebrity', 'music', 'film', 'entertainment']
        }

        for category, keywords in category_keywords.items():
            if any(keyword in text_lower for keyword in keywords):
                return category
        return NewsCategory.GENERAL

    def analyze_sentiment(self, text: str) -> Sentiment:
        positive_words = ['good', 'great', 'excellent', 'positive', 'success', 'win', 'happy']
        negative_words = ['bad', 'terrible', 'negative', 'failure', 'lose', 'sad', 'crisis']

        text_lower = text.lower()
        positive_count = sum(1 for word in positive_words if word in text_lower)
        negative_count = sum(1 for word in negative_words if word in text_lower)

        if positive_count > negative_count:
            return Sentiment.POSITIVE
        elif negative_count > positive_count:
            return Sentiment.NEGATIVE
        else:
            return Sentiment.NEUTRAL

    def extract_keywords(self, text: str, num_keywords: int = 5) -> List[str]:
        words = text.lower().split()
        common_words = {'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by'}
        filtered_words = [word for word in words if word not in common_words and len(word) > 3]

        word_freq = {}
        for word in filtered_words:
            word_freq[word] = word_freq.get(word, 0) + 1

        sorted_words = sorted(word_freq.items(), key=lambda x: x[1], reverse=True)
        return [word for word, freq in sorted_words[:num_keywords]]

