# ==================== Syntax Highlighting ====================

class SyntaxHighlighter(ABC):
    """Abstract base class for syntax highlighting."""

    @abstractmethod
    def highlight(self, code: str) -> str:
        """Apply syntax highlighting to code."""
        pass

class PythonHighlighter(SyntaxHighlighter):
    """Syntax highlighter for Python."""

    def highlight(self, code: str) -> str:
        # Simple keyword highlighting for demonstration
        keywords = {'def', 'class', 'if', 'else', 'elif', 'for', 'while', 
                   'import', 'from', 'as', 'return', 'try', 'except', 'with'}

        highlighted = []
        for line in code.split('\n'):
            for word in line.split():
                if word in keywords:
                    highlighted.append(f'<span class="keyword">{word}</span>')
                else:
                    highlighted.append(word)
            highlighted.append('\n')
        return ' '.join(highlighted)

class JavaScriptHighlighter(SyntaxHighlighter):
    """Syntax highlighter for JavaScript."""

    def highlight(self, code: str) -> str:
        keywords = {'function', 'var', 'let', 'const', 'if', 'else', 'for', 
                   'while', 'return', 'try', 'catch', 'async', 'await'}

        highlighted = []
        for line in code.split('\n'):
            for word in line.split():
                if word in keywords:
                    highlighted.append(f'<span class="keyword">{word}</span>')
                else:
