            highlighted.append('\n')
        return ' '.join(highlighted)

class JavaHighlighter(SyntaxHighlighter):
    """Syntax highlighter for Java."""

    def highlight(self, code: str) -> str:
        keywords = {'public', 'private', 'class', 'void', 'static', 'int', 
                   'String', 'if', 'else', 'for', 'while', 'return', 'try'}

        highlighted = []
        for line in code.split('\n'):
            for word in line.split():
                if word in keywords:
