                else:
                    highlighted.append(word)
            highlighted.append('\n')
        return ' '.join(highlighted)

class CppHighlighter(SyntaxHighlighter):
    """Syntax highlighter for C++."""

    def highlight(self, code: str) -> str:
        keywords = {'#include', 'using', 'namespace', 'int', 'void', 'class', 
                   'public', 'private', 'if', 'else', 'for', 'while', 'return'}

        highlighted = []
        for line in code.split('\n'):
            for word in line.split():
