class SyntaxHighlightingFactory:
    """Factory to create appropriate syntax highlighters."""

    @staticmethod
    def create_highlighter(language: Language) -> SyntaxHighlighter:
        """Create a syntax highlighter for the given language."""
        highlighters = {
