# ==================== Code Completion ====================

class CodeCompleter:
    """Provides code completion suggestions."""

    def __init__(self):
        # Predefined code snippets for different languages
        self.snippets = {
            Language.PYTHON: {
                'for loop': 'for i in range(n):\n    ',
                'function': 'def function_name():\n    ',
                'class': 'class ClassName:\n    def __init__(self):\n        '
            },
            Language.JAVASCRIPT: {
                'function': 'function functionName() {\n    ',
                'arrow function': 'const functionName = () => {\n    ',
                'for loop': 'for (let i = 0; i < n; i++) {\n    '
            },
            Language.JAVA: {
                'main method': 'public static void main(String[] args) {\n    ',
                'class': 'public class ClassName {\n    ',
                'for loop': 'for (int i = 0; i < n; i++) {\n    '
            },
            Language.CPP: {
                'main function': 'int main() {\n    ',
                'class': 'class ClassName {\npublic:\n    ',
                'for loop': 'for (int i = 0; i < n; i++) {\n    '
            }
        }

        # Language keywords
        self.keywords = {
            Language.PYTHON: ['def', 'class', 'if', 'else', 'for', 'while', 'import', 'from'],
            Language.JAVASCRIPT: ['function', 'const', 'let', 'var', 'if', 'else', 'for', 'while'],
            Language.JAVA: ['public', 'private', 'class', 'void', 'static', 'if', 'else', 'for'],
            Language.CPP: ['int', 'void', 'class', 'public', 'private', 'if', 'else', 'for']
        }

    def get_suggestions(self, language: Language, prefix: str) -> List[str]:
        """Get completion suggestions based on language and current prefix."""
        suggestions = []

        # Add keywords
        if language in self.keywords:
            suggestions.extend([kw for kw in self.keywords[language] if kw.startswith(prefix)])

        # Add snippets
        if language in self.snippets:
            suggestions.extend([name for name in self.snippets[language].keys() 
                              if name.startswith(prefix)])

        return suggestions[:10]  # Limit to 10 suggestions

# ==================== Version Control ====================

class VersionControlSystem:
    """Manages version control for code snippets."""

    def __init__(self):
        self.change_history: Dict[str, List[ChangeRecord]] = {}

    def record_change(self, snippet_id: str, user_id: str, 
                     old_content: str, new_content: str) -> ChangeRecord:
        """Record a change to a code snippet."""
        change = ChangeRecord(
            id=str(uuid.uuid4()),
            snippet_id=snippet_id,
            user_id=user_id,
            timestamp=datetime.now(),
            old_content=old_content,
            new_content=new_content
        )

        if snippet_id not in self.change_history:
            self.change_history[snippet_id] = []

        self.change_history[snippet_id].append(change)
        return change

    def get_history(self, snippet_id: str) -> List[ChangeRecord]:
        """Get change history for a snippet."""
        return self.change_history.get(snippet_id, [])

    def revert_to_version(self, snippet_id: str, version_id: str) -> Optional[str]:
        """Revert a snippet to a specific version."""
        if snippet_id not in self.change_history:
            return None

        for change in self.change_history[snippet_id]:
            if change.id == version_id:
                return change.old_content

        return None

# ==================== Real-time Collaboration ====================

class CollaborationSession:
    """Manages a real-time collaboration session."""

    def __init__(self, notebook_id: str):
        self.notebook_id = notebook_id
        self.connected_users: Set[str] = set()
        self.cursors: Dict[str, Tuple[int, int]] = {}  # User ID -> (line, column)
        self.locks: Dict[str, str] = {}  # Snippet ID -> User ID who locked it

    def connect_user(self, user_id: str):
        """Add user to collaboration session."""
        self.connected_users.add(user_id)

    def disconnect_user(self, user_id: str):
        """Remove user from collaboration session."""
        if user_id in self.connected_users:
            self.connected_users.remove(user_id)

        # Remove user's cursor
        if user_id in self.cursors:
            del self.cursors[user_id]

        # Release locks held by user
        for snippet_id, locker in list(self.locks.items()):
            if locker == user_id:
                del self.locks[snippet_id]

    def update_cursor(self, user_id: str, line: int, column: int):
        """Update user's cursor position."""
        self.cursors[user_id] = (line, column)

    def lock_snippet(self, snippet_id: str, user_id: str) -> bool:
        """Lock a snippet for editing by a specific user."""
        if snippet_id in self.locks and self.locks[snippet_id] != user_id:
            return False  # Already locked by someone else

        self.locks[snippet_id] = user_id
        return True

    def unlock_snippet(self, snippet_id: str, user_id: str):
        """Unlock a snippet."""
        if snippet_id in self.locks and self.locks[snippet_id] == user_id:
            del self.locks[snippet_id]

class CollaborationManager:
    """Manages all collaboration sessions."""

    def __init__(self):
        self.sessions: Dict[str, CollaborationSession] = {}

    def get_or_create_session(self, notebook_id: str) -> CollaborationSession:
        """Get existing session or create new one."""
        if notebook_id not in self.sessions:
            self.sessions[notebook_id] = CollaborationSession(notebook_id)
        return self.sessions[notebook_id]

    def remove_session(self, notebook_id: str):
        """Remove a collaboration session."""
        if notebook_id in self.sessions:
            del self.sessions[notebook_id]

# ==================== Search Functionality ====================

class SearchEngine:
    """Provides search functionality across notebooks."""

    def __init__(self):
        self.index: Dict[str, Dict[str, List[Tuple[str, str]]]] = {}  # term -> notebook_id -> [(snippet_id, content)]

    def index_snippet(self, notebook_id: str, snippet_id: str, content: str):
        """Index a code snippet for searching."""
        terms = self._extract_terms(content)

        for term in terms:
            if term not in self.index:
                self.index[term] = {}

            if notebook_id not in self.index[term]:
                self.index[term][notebook_id] = []

            self.index[term][notebook_id].append((snippet_id, content))

    def search(self, query: str, notebook_id: Optional[str] = None) -> List[Dict[str, Any]]:
        """Search for code snippets matching the query."""
        terms = self._extract_terms(query)
        results = []

        for term in terms:
            if term in self.index:
                for nb_id, snippets in self.index[term].items():
                    if notebook_id and nb_id != notebook_id:
                        continue

                    for snippet_id, content in snippets:
                        if term.lower() in content.lower():
                            results.append({
                                'notebook_id': nb_id,
                                'snippet_id': snippet_id,
                                'content_preview': content[:100],
                                'match_term': term
                            })

        return results

    def _extract_terms(self, text: str) -> List[str]:
        """Extract search terms from text."""
        # Simple term extraction - split by non-alphanumeric characters
        return [term.lower() for term in re.findall(r'\w+', text) if len(term) > 2]

