    """Syntax highlighter for Python."""

    def highlight(self, code: str) -> str:
        # Simple keyword highlighting for demonstration
        keywords = {'def', 'class', 'if', 'else', 'elif', 'for', 'while', 
                   'import', 'from', 'as', 'return', 'try', 'except', 'with'}

        highlighted = []
        for line in code.split('\n'):
            for word in line.split():
                if word in keywords:
                    highlighted.append(f'<span class="keyword">{word}</span>')
                else:
                    highlighted.append(word)
            highlighted.append('\n')
        return ' '.join(highlighted)

