    def record_change(self, snippet_id: str, user_id: str, 
                     old_content: str, new_content: str) -> ChangeRecord:
        """Record a change to a code snippet."""
        change = ChangeRecord(
            id=str(uuid.uuid4()),
            snippet_id=snippet_id,
            user_id=user_id,
            timestamp=datetime.now(),
            old_content=old_content,
            new_content=new_content
        )

        if snippet_id not in self.change_history:
            self.change_history[snippet_id] = []

        self.change_history[snippet_id].append(change)
        return change

    def get_history(self, snippet_id: str) -> List[ChangeRecord]:
        """Get change history for a snippet."""
        return self.change_history.get(snippet_id, [])

    def revert_to_version(self, snippet_id: str, version_id: str) -> Optional[str]:
        """Revert a snippet to a specific version."""
        if snippet_id not in self.change_history:
            return None

        for change in self.change_history[snippet_id]:
            if change.id == version_id:
                return change.old_content

        return None

