class CollaborationSession:
    """Manages a real-time collaboration session."""

    def __init__(self, notebook_id: str):
        self.notebook_id = notebook_id
        self.connected_users: Set[str] = set()
        self.cursors: Dict[str, Tuple[int, int]] = {}  # User ID -> (line, column)
        self.locks: Dict[str, str] = {}  # Snippet ID -> User ID who locked it

    def connect_user(self, user_id: str):
        """Add user to collaboration session."""
        self.connected_users.add(user_id)

    def disconnect_user(self, user_id: str):
        """Remove user from collaboration session."""
        if user_id in self.connected_users:
            self.connected_users.remove(user_id)

        # Remove user's cursor
        if user_id in self.cursors:
            del self.cursors[user_id]

        # Release locks held by user
        for snippet_id, locker in list(self.locks.items()):
            if locker == user_id:
                del self.locks[snippet_id]

    def update_cursor(self, user_id: str, line: int, column: int):
        """Update user's cursor position."""
        self.cursors[user_id] = (line, column)

    def lock_snippet(self, snippet_id: str, user_id: str) -> bool:
        """Lock a snippet for editing by a specific user."""
        if snippet_id in self.locks and self.locks[snippet_id] != user_id:
            return False  # Already locked by someone else

        self.locks[snippet_id] = user_id
        return True

    def unlock_snippet(self, snippet_id: str, user_id: str):
        """Unlock a snippet."""
        if snippet_id in self.locks and self.locks[snippet_id] == user_id:
            del self.locks[snippet_id]

class CollaborationManager:
    """Manages all collaboration sessions."""

    def __init__(self):
        self.sessions: Dict[str, CollaborationSession] = {}

    def get_or_create_session(self, notebook_id: str) -> CollaborationSession:
        """Get existing session or create new one."""
        if notebook_id not in self.sessions:
            self.sessions[notebook_id] = CollaborationSession(notebook_id)
        return self.sessions[notebook_id]

    def remove_session(self, notebook_id: str):
        """Remove a collaboration session."""
        if notebook_id in self.sessions:
            del self.sessions[notebook_id]

