class SearchEngine:
    """Provides search functionality across notebooks."""

    def __init__(self):
        self.index: Dict[str, Dict[str, List[Tuple[str, str]]]] = {}  # term -> notebook_id -> [(snippet_id, content)]

    def index_snippet(self, notebook_id: str, snippet_id: str, content: str):
        """Index a code snippet for searching."""
        terms = self._extract_terms(content)

        for term in terms:
            if term not in self.index:
                self.index[term] = {}

            if notebook_id not in self.index[term]:
                self.index[term][notebook_id] = []

            self.index[term][notebook_id].append((snippet_id, content))

    def search(self, query: str, notebook_id: Optional[str] = None) -> List[Dict[str, Any]]:
        """Search for code snippets matching the query."""
        terms = self._extract_terms(query)
        results = []

        for term in terms:
            if term in self.index:
                for nb_id, snippets in self.index[term].items():
                    if notebook_id and nb_id != notebook_id:
                        continue

                    for snippet_id, content in snippets:
                        if term.lower() in content.lower():
                            results.append({
                                'notebook_id': nb_id,
                                'snippet_id': snippet_id,
                                'content_preview': content[:100],
                                'match_term': term
                            })

        return results

    def _extract_terms(self, text: str) -> List[str]:
        """Extract search terms from text."""
        # Simple term extraction - split by non-alphanumeric characters
        return [term.lower() for term in re.findall(r'\w+', text) if len(term) > 2]

