class CodeSnippet:
    def __init__(self, snippet_id: str, language: str, content: str = "", created_by: str = ""):
        self.snippet_id = snippet_id
        self.language = language
        self.content = content
        self.created_by = created_by
        self.created_at = datetime.now()
        self.updated_at = datetime.now()
        self.versions: List[Dict[str, Any]] = []
        self.save_version()

    def save_version(self):
        self.versions.append({
            "content": self.content,
            "timestamp": datetime.now(),
            "updated_by": self.created_by
        })

    def revert_to_version(self, version_index: int) -> bool:
        if 0 <= version_index < len(self.versions):
            self.content = self.versions[version_index]["content"]
            self.updated_at = datetime.now()
            self.save_version()
            return True
        return False


class Notebook:
    def __init__(self, notebook_id: str, name: str, owner_id: str, is_public: bool = False):
        self.notebook_id = notebook_id
        self.name = name
        self.owner_id = owner_id
        self.is_public = is_public
        self.created_at = datetime.now()
        self.snippets: Dict[str, CodeSnippet] = {}
        self.access_control: Dict[str, UserRole] = {owner_id: UserRole.OWNER}

    def add_snippet(self, snippet: CodeSnippet):
        self.snippets[snippet.snippet_id] = snippet

    def remove_snippet(self, snippet_id: str) -> bool:
        return snippet_id in self.snippets and self.snippets.pop(snippet_id, None) is not None

    def grant_access(self, user_id: str, role: UserRole) -> bool:
        self.access_control[user_id] = role
        return True

    def revoke_access(self, user_id: str) -> bool:
        if user_id == self.owner_id:
            return False
        return user_id in self.access_control and self.access_control.pop(user_id, None) is not None

    def can_access(self, user_id: str, required_role: UserRole = UserRole.VIEWER) -> bool:
        if self.is_public and required_role == UserRole.VIEWER:
            return True
        if user_id not in self.access_control:
            return False
        user_role = self.access_control[user_id]
        role_hierarchy = {UserRole.OWNER: 3, UserRole.EDITOR: 2, UserRole.VIEWER: 1}
        return role_hierarchy[user_role] >= role_hierarchy[required_role]


