from dataclasses import dataclass, asdict
from abc import ABC, abstractmethod

# ==================== Enums and Constants ====================

class TaskStatus(Enum):
    """Enumeration for task status."""
    PENDING = "pending"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"

class PriorityLevel(Enum):
    """Enumeration for task priority levels."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"

class NotificationType(Enum):
    """Enumeration for notification types."""
    TASK_ASSIGNED = "task_assigned"
    DEADLINE_APPROACHING = "deadline_approaching"
    DEADLINE_PASSED = "deadline_passed"
    STATUS_UPDATED = "status_updated"
    COMMENT_ADDED = "comment_added"

# ==================== Data Classes ====================

@dataclass
class User:
    """Represents a user in the system."""
    username: str
    password: str  # In production, this should be hashed
    email: str

    def to_dict(self) -> Dict:
        """Convert user object to dictionary for serialization."""
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict) -> 'User':
        """Create user object from dictionary."""
        return cls(**data)

@dataclass
class Comment:
    """Represents a comment on a task."""
    author: str
    content: str
    timestamp: datetime

    def to_dict(self) -> Dict:
        """Convert comment to dictionary for serialization."""
        return {
            "author": self.author,
            "content": self.content,
            "timestamp": self.timestamp.isoformat()
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Comment':
        """Create comment from dictionary."""
        return cls(
            author=data["author"],
            content=data["content"],
            timestamp=datetime.fromisoformat(data["timestamp"])
        )

@dataclass
class Task:
    """Represents a task in the system."""
    task_id: str
    title: str
    description: str
    created_by: str
    assigned_to: str
    status: TaskStatus
    priority: PriorityLevel
    deadline: datetime
    created_at: datetime
    updated_at: datetime
    comments: List[Comment]

    def to_dict(self) -> Dict:
        """Convert task to dictionary for serialization."""
        return {
            "task_id": self.task_id,
            "title": self.title,
            "description": self.description,
            "created_by": self.created_by,
            "assigned_to": self.assigned_to,
            "status": self.status.value,
            "priority": self.priority.value,
            "deadline": self.deadline.isoformat(),
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
            "comments": [comment.to_dict() for comment in self.comments]
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Task':
        """Create task from dictionary."""
        return cls(
            task_id=data["task_id"],
            title=data["title"],
            description=data["description"],
            created_by=data["created_by"],
            assigned_to=data["assigned_to"],
            status=TaskStatus(data["status"]),
            priority=PriorityLevel(data["priority"]),
            deadline=datetime.fromisoformat(data["deadline"]),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
            comments=[Comment.from_dict(c) for c in data["comments"]]
        )

    def is_overdue(self) -> bool:
        """Check if task is overdue."""
        return datetime.now() > self.deadline and self.status != TaskStatus.COMPLETED

    def deadline_approaching(self, days_threshold: int = 2) -> bool:
        """Check if deadline is approaching within specified days."""
        time_until_deadline = self.deadline - datetime.now()
        return 0 < time_until_deadline.days <= days_threshold and self.status != TaskStatus.COMPLETED

