class OfficeTaskScheduler:
    """Main system class for managing office tasks."""

    def __init__(self, storage: Storage = None):
        """Initialize the task scheduler with storage."""
        self.storage = storage or JSONStorage()
        self.current_user: Optional[User] = None
        self.task_counter = 0
        self.notification_counter = 0

        # Load task counter from existing tasks
        tasks = self.storage.get_all_tasks()
        if tasks:
            self.task_counter = max(int(task.task_id.split('_')[1]) for task in tasks)

    def login(self, username: str, password: str) -> bool:
        """Login a user."""
        user = self.storage.get_user(username)

        if user and user.password == password:  # In production, use hashed passwords
            self.current_user = user
            self._check_deadline_notifications()
            return True

        return False

    def logout(self) -> None:
        """Logout current user."""
        self.current_user = None

    def register_user(self, username: str, password: str, email: str) -> Tuple[bool, str]:
        """Register a new user."""
        if self.storage.get_user(username):
            return False, "Username already exists"

        user = User(username=username, password=password, email=email)
        self.storage.save_user(user)
        return True, "User registered successfully"

    def create_task(self, title: str, description: str, assigned_to: str, 
                   priority: PriorityLevel, deadline: datetime) -> Tuple[bool, str, Optional[str]]:
        """Create a new task."""
        # Check if current user is logged in
        if not self.current_user:
            return False, "User not logged in", None

        # Check if assigned user exists
        if not self.storage.get_user(assigned_to):
            return False, f"User '{assigned_to}' does not exist", None

        # Check if deadline is in the past
        if deadline < datetime.now():
            return False, "Deadline cannot be in the past", None

        # Generate task ID
        self.task_counter += 1
        task_id = f"task_{self.task_counter}"

        # Create task
        task = Task(
            task_id=task_id,
            title=title,
            description=description,
            created_by=self.current_user.username,
            assigned_to=assigned_to,
            status=TaskStatus.PENDING,
            priority=priority,
            deadline=deadline,
            created_at=datetime.now(),
            updated_at=datetime.now(),
            comments=[]
        )

        # Save task
        self.storage.save_task(task)

        # Create notification for assigned user
        self._create_notification(
            user=assigned_to,
            message=f"New task assigned: '{title}' by {self.current_user.username}",
            notification_type=NotificationType.TASK_ASSIGNED,
            task_id=task_id
        )

        return True, "Task created successfully", task_id

