class MazeGenerator:
    """Generates mazes of varying difficulty levels."""

    @staticmethod
    def generate(level: int, width: int = 15, height: int = 15) -> List[List[CellType]]:
        """
        Generate a maze based on level difficulty.
        Higher levels have more complex layouts and obstacles.
        """
        # Initialize with walls
        maze = [[CellType.WALL for _ in range(width)] for _ in range(height)]

        # Create paths using randomized Prim's algorithm
        start_x, start_y = 1, 1
        maze[start_y][start_x] = CellType.START

        # Add goal
        goal_x, goal_y = width - 2, height - 2
        maze[goal_y][goal_x] = CellType.GOAL

        # Create main path
        frontier = [(start_x + 2, start_y), (start_x, start_y + 2)]
        while frontier:
            x, y = random.choice(frontier)
            frontier.remove((x, y))

            if 0 < x < width - 1 and 0 < y < height - 1:
                neighbors = []
                if x > 1 and maze[y][x-2] == CellType.EMPTY:
                    neighbors.append((x-2, y))
                if x < width - 2 and maze[y][x+2] == CellType.EMPTY:
                    neighbors.append((x+2, y))
                if y > 1 and maze[y-2][x] == CellType.EMPTY:
                    neighbors.append((x, y-2))
                if y < height - 2 and maze[y+2][x] == CellType.EMPTY:
                    neighbors.append((x, y+2))

                if neighbors:
                    nx, ny = random.choice(neighbors)
                    maze[y][x] = CellType.EMPTY
                    maze[ny][nx] = CellType.EMPTY
                    maze[(y + ny)//2][(x + nx)//2] = CellType.EMPTY

                    # Add new frontier cells
                    for dx, dy in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                        new_x, new_y = x + dx, y + dy
                        if 0 < new_x < width - 1 and 0 < new_y < height - 1:
                            if maze[new_y][new_x] == CellType.WALL:
                                frontier.append((new_x, new_y))

        # Add blocks based on level
        block_count = min(level * 3, 20)  # More blocks at higher levels
        blocks_added = 0

        while blocks_added < block_count:
            x, y = random.randint(1, width-2), random.randint(1, height-2)
            if maze[y][x] == CellType.EMPTY:
                maze[y][x] = CellType.BLOCK
                blocks_added += 1

        # Ensure there's at least one path from start to goal
        MazeGenerator._ensure_path_exists(maze, start_x, start_y, goal_x, goal_y)

        return maze

    @staticmethod
    def _ensure_path_exists(maze: List[List[CellType]], start_x: int, start_y: int, 
                           goal_x: int, goal_y: int):
        """Ensure there's a valid path from start to goal using DFS."""
        height = len(maze)
        width = len(maze[0])
        visited = [[False for _ in range(width)] for _ in range(height)]
        stack = [(start_x, start_y)]

        while stack:
            x, y = stack.pop()
            if x == goal_x and y == goal_y:
