    """Calculates drift scores with team coordination bonuses"""

    @staticmethod
    def calculate_individual_score(drift_angle: float, duration: float, 
                                 speed: float, zone_multiplier: float = 1.0) -> float:
        """Calculate individual drift score"""
        angle_score = min(drift_angle / 45.0, 2.0) * 100  # Max angle 90 degrees
        duration_score = duration * 50  # 50 points per second
        speed_score = speed * 0.5  # 0.5 points per unit speed

        base_score = (angle_score + duration_score + speed_score) * zone_multiplier
        return round(base_score, 2)

    @staticmethod
    def calculate_team_sync_bonus(players_scores: List[float], sync_window: float = 1.0) -> float:
        """Calculate team synchronization bonus"""
        if len(players_scores) < 2:
            return 0.0

        avg_score = sum(players_scores) / len(players_scores)
        variance = sum((score - avg_score) ** 2 for score in players_scores) / len(players_scores)

        # Lower variance = better synchronization
        sync_quality = max(0, 1 - variance / 10000)

        # Bonus is 25% of average score for perfect sync
        bonus = avg_score * 0.25 * sync_quality
        return round(bonus, 2)

