class DependencyManager:
    """Manages dependencies between game systems to ensure proper initialization order"""

    def __init__(self):
        self._dependencies = {
            'multiplayer': [],
            'coordination': [],
            'scoring': ['multiplayer', 'coordination'],
            'track_editor': ['multiplayer', 'coordination']
        }
        self._initialized = set()

    def can_initialize(self, system_name: str) -> bool:
        """Check if all dependencies for a system are met"""
        deps = self._dependencies.get(system_name, [])
        return all(dep in self._initialized for dep in deps)

    def mark_initialized(self, system_name: str):
        """Mark a system as initialized"""
        self._initialized.add(system_name)

    def get_status(self) -> Dict[str, bool]:
        """Get initialization status of all systems"""
        return {
            system: system in self._initialized
            for system in self._dependencies.keys()
        }

