@dataclass
class Vector2D:
    x: float
    y: float

    def __add__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    def magnitude(self) -> float:
        return math.sqrt(self.x**2 + self.y**2)

    def normalized(self) -> 'Vector2D':
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / mag, self.y / mag)

    def dot(self, other: 'Vector2D') -> float:
        return self.x * other.x + self.y * other.y

    def rotate(self, angle: float) -> 'Vector2D':
        """Rotate vector by angle in radians"""
        cos_a = math.cos(angle)
        sin_a = math.sin(angle)
        return Vector2D(
            self.x * cos_a - self.y * sin_a,
            self.x * sin_a + self.y * cos_a
        )

class DriftPhysics:
    """Realistic physics simulation for drifting mechanics"""

    def __init__(self):
        self.gravity = 9.81
        self.friction_coefficient = 0.8
        self.drift_friction = 0.4
        self.air_resistance = 0.01

    def calculate_drift_angle(self, velocity: Vector2D, heading: Vector2D) -> float:
        """Calculate drift angle between velocity and heading vectors"""
        if velocity.magnitude() == 0:
            return 0.0

        norm_vel = velocity.normalized()
        norm_head = heading.normalized()

        dot_product = norm_vel.dot(norm_head)
        dot_product = max(-1.0, min(1.0, dot_product))

        angle = math.acos(dot_product)
        cross_product = norm_vel.x * norm_head.y - norm_vel.y * norm_head.x

        return angle if cross_product > 0 else -angle

    def calculate_drift_score(self, angle: float, duration: float, speed: float) -> float:
        """Calculate drift score based on angle, duration, and speed"""
        angle_score = abs(angle) * 10
        duration_score = duration * 5
        speed_score = speed * 2

        return angle_score + duration_score + speed_score

