# Game Constants and Enums
# ============================================================================

class Difficulty(Enum):
    EASY = "Easy"
    MEDIUM = "Medium"
    HARD = "Hard"
    EXPERT = "Expert"

class TrackType(Enum):
    CIRCUIT = "Circuit"
    DRIFT = "Drift Zone"
    CITY = "City Streets"
    MOUNTAIN = "Mountain Pass"
    SPEED = "Speedway"

class AgentType(Enum):
    AGGRESSIVE = "Aggressive"
    BALANCED = "Balanced"
    DEFENSIVE = "Defensive"
    PRECISION = "Precision"
    STYLISH = "Stylish"

# ============================================================================
# Core Data Structures
# ============================================================================

@dataclass
class Vector2D:
    x: float
    y: float

    def magnitude(self) -> float:
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self) -> 'Vector2D':
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x/mag, self.y/mag)

    def dot(self, other: 'Vector2D') -> float:
        return self.x * other.x + self.y * other.y

    def __add__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

@dataclass
class CarProperties:
    max_speed: float = 200.0
    acceleration: float = 30.0
    braking: float = 50.0
    handling: float = 0.8
    drift_factor: float = 1.2
    weight: float = 1500.0
    tire_grip: float = 0.9

@dataclass
class TrackSegment:
    start: Vector2D
    end: Vector2D
    width: float
    is_drift_zone: bool
    difficulty_multiplier: float

    def length(self) -> float:
        return math.sqrt((self.end.x - self.start.x)**2 + (self.end.y - self.start.y)**2)

    def direction(self) -> Vector2D:
        return Vector2D(self.end.x - self.start.x, self.end.y - self.start.y).normalize()

@dataclass
class Track:
    name: str
    track_type: TrackType
    difficulty: Difficulty
    segments: List[TrackSegment]
    total_length: float
    drift_zones: int
    obstacles: List[Vector2D]

    def __post_init__(self):
        self.total_length = sum(seg.length() for seg in self.segments)
        self.drift_zones = sum(1 for seg in self.segments if seg.is_drift_zone)

@dataclass
class DriftScore:
    angle_score: float
    speed_score: float
    style_score: float
    continuity_score: float

    @property
    def total(self) -> float:
        return (self.angle_score * 0.4 + 
                self.speed_score * 0.3 + 
                self.style_score * 0.2 + 
                self.continuity_score * 0.1)

# ============================================================================
# AI Agent Base Class
# ============================================================================

class AIAgent(ABC):
    def __init__(self, name: str, agent_type: AgentType, car_props: CarProperties):
        self.name = name
        self.agent_type = agent_type
        self.car_props = car_props
        self.position = Vector2D(0, 0)
        self.velocity = Vector2D(0, 0)
        self.direction = Vector2D(1, 0)
        self.current_speed = 0.0
        self.is_drifting = False
        self.drift_angle = 0.0
        self.race_time = 0.0
        self.drift_score = DriftScore(0, 0, 0, 0)
        self.lap_count = 0
        self.total_drift_score = 0.0
        self.learning_rate = 0.1
        self.memory: List[Dict] = []

        # Agent-specific parameters
        if agent_type == AgentType.AGGRESSIVE:
            self.risk_tolerance = 0.8
            self.drift_aggression = 0.9
        elif agent_type == AgentType.DEFENSIVE:
            self.risk_tolerance = 0.3
            self.drift_aggression = 0.5
        elif agent_type == AgentType.PRECISION:
            self.risk_tolerance = 0.5
            self.drift_aggression = 0.7
        elif agent_type == AgentType.STYLISH:
            self.risk_tolerance = 0.6
            self.drift_aggression = 0.85
        else:  # BALANCED
            self.risk_tolerance = 0.5
            self.drift_aggression = 0.7

    @abstractmethod
    def decide_action(self, track_info: Track, other_agents: List['AIAgent'], dt: float) -> Dict[str, Any]:
        pass

    def update_position(self, dt: float):
        """Update car position based on physics"""
        acceleration_vector = self.direction * self.car_props.acceleration

        if self.is_drifting:
            # Drift physics
            drift_direction = Vector2D(
                math.cos(self.drift_angle),
                math.sin(self.drift_angle)
            )
            self.velocity = self.velocity + drift_direction * self.car_props.acceleration * dt * self.car_props.drift_factor
        else:
            self.velocity = self.velocity + acceleration_vector * dt

        # Limit speed
        speed = self.velocity.magnitude()
        if speed > self.car_props.max_speed:
            self.velocity = self.velocity.normalize() * self.car_props.max_speed

        self.position = self.position + self.velocity * dt
        self.current_speed = speed

        if speed > 0:
            self.direction = self.velocity.normalize()

    def calculate_drift_score(self, dt: float):
        """Calculate drift score based on current drift"""
        if self.is_drifting:
            # Angle score (0-100)
            angle_score = min(abs(self.drift_angle) * 50, 100)

            # Speed score (0-100)
            speed_score = min(self.current_speed / self.car_props.max_speed * 100, 100)

            # Style score (based on consistency)
            style_score = 50 + random.uniform(-10, 10) * self.drift_aggression

            self.drift_score = DriftScore(
                angle_score,
                speed_score,
                style_score,
                self.drift_score.continuity_score + 1
            )

            self.total_drift_score += self.drift_score.total * dt

    def learn_from_experience(self, success: bool, performance: float):
        """Reinforcement learning update"""
        self.memory.append({
            'success': success,
            'performance': performance,
            'timestamp': time.time()
        })

        # Keep only recent memory
        if len(self.memory) > 100:
            self.memory = self.memory[-100:]

        if success:
            self.risk_tolerance = min(self.risk_tolerance + self.learning_rate * 0.1,
